      Real u "Input signal" ;
      Modelica.Blocks.Interfaces.RealInput u1 "Optional 1st derivative of input" ;
      Modelica.Blocks.Interfaces.RealInput u2 "Optional 2nd derivative of input" ;
    equation
      y = -f;
      y1 = if use_fder then -der(y) else 0;
      y2 = if (use_fder and use_fder2) then -der(y1) else 0;
