block TotalHarmonicDistortion "Output the total harmonic distortion (THD)"
    extends Interfaces.SISO;
    parameter SI.Frequency f(start=1) "Base frequency";
    parameter Boolean useFirstHarmonic = true "THD with respect to first harmonic, if true; otherwise with respect to total RMS";

    Harmonic harmonic(
      final f=f,
      final k=1,
      final x0Cos=0,
      final x0Sin=0) ;
    RootMeanSquare rootMeanSquare(final f=f, final x0=0) ;
    Logical.GreaterThreshold greaterThreshold ;
    Interfaces.BooleanOutput valid "True, if output y is valid" ;
    Division division ;
    Nonlinear.Limiter limiter(uMin=Modelica.Constants.eps, uMax=Modelica.Constants.inf) ;
    Pythagoras pythagoras(u1IsHypotenuse=true) ;
    Logical.And andValid ;
    Sources.BooleanExpression booleanExpression(final y=not useFirstHarmonic) ;
    Logical.Switch switch1 ;
  equation
    connect(u, rootMeanSquare.u) ;
    connect(u, harmonic.u) ;
    connect(harmonic.y_rms, greaterThreshold.u) ;
    connect(division.y, y) ;
    connect(pythagoras.u1, rootMeanSquare.y) ;
    connect(pythagoras.y, division.u1) ;
    connect(pythagoras.valid, andValid.u1) ;
    connect(greaterThreshold.y, andValid.u2) ;
    connect(andValid.y, valid) ;
    connect(limiter.y, division.u2) ;
    connect(harmonic.y_rms, pythagoras.u2) ;
    connect(switch1.u1, rootMeanSquare.y) ;
    connect(harmonic.y_rms, switch1.u3) ;
    connect(booleanExpression.y, switch1.u2) ;
    connect(switch1.y, limiter.u) ;
  end TotalHarmonicDistortion;

