block IntakeManifold "Dynamics of the intake manifold"
  extends Modelica.Blocks.Icons.Block;

  parameter Real RTVmRatio = 0.41328
    "RT/V_m";
  parameter Modelica.Units.NonSI.Pressure_bar P_0 = 0.543
    "Initial value for P_m, (bar)";
  Modelica.Blocks.Interfaces.RealInput m_ai_der(unit="g/s")
    "Mass flow rate of air into manifold (g/s)";
  Modelica.Blocks.Interfaces.RealInput N(unit="rad/s") "Engine speed (rad/sec)";
  Modelica.Blocks.Interfaces.RealOutput m_ao_der(unit="g/s")
    "Mass flow rate of air out of manifold (g/s)";
  Modelica.Blocks.Interfaces.RealOutput P_m(start=P_0, fixed=true, unit="bar")
    "Intake manifold pressure (bar)";
equation
  der(P_m) = RTVmRatio*(m_ai_der - m_ao_der);
  m_ao_der = -0.366 + 0.08979*N*P_m - 0.0337*N*P_m^2 + 0.0001*N^2*P_m;
end IntakeManifold;

block SpeedControl
  "Discrete control of crankshaft speed by throttle actuation"

  parameter Real k_p = 0.0614 "Proportional gain";
  parameter Real k_I = 0.0723 "Integral gain";
  Modelica.Blocks.Interfaces.RealInput N_des(unit="rad/s", start=0) "Desired speed, (rad/s)" ;
  Modelica.Blocks.Interfaces.RealInput N(unit="rad/s", start=0) "Measured speed, (rad/s)" ;
  Modelica.Blocks.Interfaces.RealOutput Theta(start=8.9, unit="deg")
    "Throttle angle (deg)" ;
protected
  Modelica.Units.NonSI.Angle_deg x_d(start=8.973, fixed=true);
/*
initial equation
  N_des = pre(N_des);
  N = pre(N);
*/
equation
  when Clock() then
     x_d = previous(x_d) + k_I*interval()*(previous(N_des) - previous(N));
     Theta = k_p*(N_des - N) + x_d;
  end when;
end SpeedControl;

block ThrottleBody "Basic throttle body equations"
  extends Modelica.Blocks.Icons.Block;

parameter Modelica.Units.NonSI.Pressure_bar P_0 = 1 "Atmospheric pressure (bar)";
protected
  Real m_ai(start=0, fixed=true, unit="g") "Mass";
  Modelica.Units.NonSI.Angle_deg f_Theta "Auxiliary variable";
  Real g_Pm "Auxiliary variable";
public
  Modelica.Blocks.Interfaces.RealInput Theta(unit="deg") "Throttle angle (deg)";
  Modelica.Blocks.Interfaces.RealInput Pm(unit="bar")
    "Intake manifold pressure (bar)";
  Modelica.Blocks.Interfaces.RealOutput m_ai_der(unit="g/s")
    "Mass flow rate of air into manifold (g/s)";

protected
  Real tmp1;
  Real tmp2;
  Real pratio;
  Real gpratio;
equation

der(m_ai) = f_Theta * g_Pm;
f_Theta = 2.821 - 0.05231*Theta + 0.10299*Theta^2 - 0.00063*Theta^3; // different to paper 0.0063*Theta^3
// Note: If the flow direction changes, i.e. Pm>P_0 the logic will fail since sqrt(-x)
tmp1 = Pm / P_0;
tmp2 = P_0 / Pm;
pratio = min(tmp1, tmp2);
gpratio = if pratio >= 0.5 then 2*sqrt(pratio - pratio^2) else 1;
g_Pm = sign(P_0 - Pm) * gpratio;
/*
g_Pm = if Pm <= P_0/2 then 1.0 else 2/P_0*sqrt(Pm*P_0 - Pm^2);
*/
m_ai_der = der(m_ai);
end ThrottleBody;

block TorqueGeneration "Torque generation"
extends Modelica.Blocks.Icons.Block;
  parameter Real AFR = 14.6
    "Air-fuel ratio";
  parameter Real sigma = 15.0
    "Spark advance, BTDC";
  Modelica.Blocks.Interfaces.RealInput m_a(unit="g")
    "Mass of air charge in cylinder (delayed of 180deg crankshaft rotation) (g)";
  Modelica.Blocks.Interfaces.RealInput N(unit="rad/s") "Engine speed (rad/sec)";
  Modelica.Blocks.Interfaces.RealOutput T_torque_e(unit="N.m")
    "Torque generated by engine";
equation

 T_torque_e = -181.3 + 379.36*m_a + 21.91*AFR - 0.85*AFR^2 + 0.26*sigma
 - 0.0028*sigma^2 + 0.027*N - 0.000107*N^2 + 0.00048*N*sigma
 + 2.55*sigma*m_a - 0.05*sigma^2*m_a;
end TorqueGeneration;

