block Bode "Calculate quantities to plot Bode diagram"
  extends Modelica.ComplexBlocks.Icons.ComplexBlock;
  parameter Boolean useDivisor = true "Use divisor input, if true" ;
  constant Modelica.Units.SI.AmplitudeLevelDifference dB = 20 "Amplitude level difference";
  Interfaces.ComplexInput u "Dividend if useDivisor == true" ;
  Interfaces.ComplexInput divisor if useDivisor "Divisor" ;
  Blocks.Interfaces.RealOutput abs_y "Absolute value of ratio u / divisor" ;
  Blocks.Interfaces.RealOutput arg_y(unit="rad") "Angle of ratio u / divisor" ;
  Interfaces.ComplexOutput y "Quotient y = u / divisor" ;
  Sources.ComplexConstant complexOne(final k=Complex(1, 0)) if not useDivisor "Complex(1,0)" ;
  Division division(final useConjugateInput1=false, final useConjugateInput2=false);
  ComplexToPolar complexToPolar(final useConjugateInput=false) ;
  Blocks.Interfaces.RealOutput dB_y(unit="dB") "Log10 of absolute value of ratio u / divisor in dB" ;
  Blocks.Math.Log10 log10_y ;
  Blocks.Math.Gain gain(final k=dB) ;
  Blocks.Nonlinear.Limiter limiter(final uMax=Modelica.Constants.inf, final uMin=Modelica.Constants.eps) ;
equation

  connect(complexOne.y, division.u2) ;
  connect(divisor, division.u2) ;
  connect(division.u1, u) ;
  connect(division.y, y) ;
  connect(complexToPolar.u, y) ;
  connect(complexToPolar.phi, arg_y) ;
  connect(complexToPolar.len, abs_y) ;
  connect(log10_y.y, gain.u) ;
  connect(gain.y, dB_y) ;
  connect(limiter.y, log10_y.u) ;
  connect(complexToPolar.len, limiter.u) ;
end Bode;

block ComplexToPolar "Converts complex to polar representation"
  extends Modelica.ComplexBlocks.Icons.ComplexBlock;
  Blocks.Interfaces.RealOutput len ;
  Blocks.Interfaces.RealOutput phi(unit="rad") ;
  Interfaces.ComplexInput u;
  parameter Boolean useConjugateInput=false
    "If true, input is processed conjugate complex";
equation
  len = (u.re^2 + u.im^2)^0.5;
  phi = (if useConjugateInput then Modelica.Math.atan2(-u.im, u.re) else
    Modelica.Math.atan2(u.im, u.re));
end ComplexToPolar;

