  parameter SI.Resistance R=10000.0 "Damping resistance";
  parameter SI.Resistance R1=10000.0 "Arbitrary high resistance";
  parameter SI.Resistance R2=(A - 1)*R1 "Calculated resistance to reach amplification A";
