  Modelica.Electrical.Analog.Basic.Inductor l(L=L, i(fixed=true, start=0));
  Modelica.Electrical.Analog.Sensors.VoltageSensor vOut ;
equation
  connect(opAmp.out, r.p) ;
  connect(opAmp.out, r2.p) ;
  connect(r2.n, r1.p) ;
  connect(r2.n, opAmp.in_n) ;
  connect(r1.n, ground.p) ;
  connect(r.n, opAmp.in_p) ;
  connect(l.n, ground.p) ;
  connect(r.n, l.p) ;
  connect(c.p, l.p) ;
