model ParallelResonance "Parallel resonance circuit"
  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  Sources.SineCurrentVariableFrequencyAndAmplitude sineCurrent(
      useConstantAmplitude=true,                               phi(fixed=true));
  Basic.Ground ground1;
  Basic.Resistor resistor1(R=0.5) ;
  Basic.Inductor inductor1(i(fixed=true), L=0.1/(2*pi)) ;
  Basic.Capacitor capacitor1(v(fixed=true), C=0.001/(2*pi)) ;
  Sensors.VoltageSensor voltageSensor1 ;
  Blocks.Sources.Ramp ramp(
    height=200,
    duration=1,
    offset=0,
    startTime=0);
  Sources.CosineCurrentVariableFrequencyAndAmplitude cosineCurrent(
      useConstantAmplitude=true, phi(fixed=true)) ;
  Basic.Ground ground2;
  Basic.Resistor resistor2(R=0.5) ;
  Basic.Inductor inductor2(i(fixed=true), L=0.1/(2*pi)) ;
  Basic.Capacitor capacitor2(v(fixed=true), C=0.001/(2*pi)) ;
  Sensors.VoltageSensor voltageSensor2 ;
equation
  connect(sineCurrent.p, ground1.p);
  connect(ramp.y, sineCurrent.f) ;
  connect(ground1.p, inductor1.n);
  connect(sineCurrent.n, resistor1.p) ;
  connect(resistor1.n, inductor1.p);
  connect(ground1.p, capacitor1.n);
  connect(sineCurrent.n, capacitor1.p) ;
  connect(sineCurrent.n, voltageSensor1.p) ;
  connect(ground1.p, voltageSensor1.n);
  connect(cosineCurrent.p, ground2.p);
  connect(ground2.p, inductor2.n);
  connect(cosineCurrent.n, resistor2.p) ;
  connect(resistor2.n, inductor2.p);
  connect(ground2.p, capacitor2.n);
  connect(cosineCurrent.n, capacitor2.p) ;
  connect(cosineCurrent.n, voltageSensor2.p) ;
  connect(ground2.p, voltageSensor2.n);
  connect(ramp.y, cosineCurrent.f) ;
end ParallelResonance;

