  connect(voltage2.p, currentToVoltageAdaptor2a.pin_p) ;
  connect(voltage2.n, currentToVoltageAdaptor2a.pin_n) ;
  connect(voltageToCurrentAdaptor2a.pin_p, inductor2.p);
