  Modelica.Blocks.Interfaces.RealOutput i(unit="A")
    "Current needed to drive the oneport according to v, dv";
  Modelica.Electrical.Analog.Basic.Ground ground;
equation

  connect(voltageToCurrent.f, i) ;
  connect(voltageToCurrent.p, v) ;
  connect(voltageToCurrent.pder, dv) ;
  connect(voltageToCurrent.pin_p, capacitor.p) ;
  connect(ground.p, capacitor.n);
  connect(voltageToCurrent.pin_n, ground.p) ;
end InverseCapacitor;

