    {{if anyTrue({ks==kDegraded[i,1] and kp==kDegraded[i,2] for i in 1:size(kDegraded,1)}) then
      cellDataDegraded else cellDataOriginal for kp in 1:Np} for ks in 1:Ns}
    "Matrix of cell data";
