block BusTranscription "Transcribe bus signals"
  extends Modelica.Blocks.Icons.Block;
  parameter Integer Ns(final min = 1) = 1 "Number of series connected cells";
  parameter Integer Np(final min = 1) = 1 "Number of parallel connected cells";
  Modelica.Electrical.Batteries.Interfaces.StackBus stackBus(Np=Np, Ns=Ns)
    "Stack bus" ;
  Modelica.Electrical.Batteries.Interfaces.StackBusArrays stackBusArrays(Np=Np,
      Ns=Ns) "Stack bus with signal arrays" ;
protected
  Modelica.Blocks.Math.Gain gainV[Ns,Np](each k=1);
  Modelica.Blocks.Math.Gain gainI[Ns,Np](each k=1);
  Modelica.Blocks.Math.Gain gainSOC[Ns,Np](each k=1);
  Modelica.Blocks.Math.Gain gainP[Ns,Np](each k=1);
  Modelica.Blocks.Math.Gain gainLosses[Ns,Np](each k=1);
  Modelica.Blocks.Math.Gain gainT[Ns,Np](each k=1);
equation
  connect(gainV.y, stackBusArrays.v) ;
  connect(gainI.y, stackBusArrays.i) ;
  connect(gainSOC.y, stackBusArrays.soc) ;
  connect(gainP.y, stackBusArrays.power) ;
  connect(gainLosses.y, stackBusArrays.lossPower) ;
  connect(gainT.y, stackBusArrays.T) ;
  connect(gainV.u, stackBus.cellBus.v) ;
  connect(gainI.u, stackBus.cellBus.i) ;
  connect(gainSOC.u, stackBus.cellBus.soc) ;
  connect(gainP.u, stackBus.cellBus.power) ;
  connect(gainLosses.u, stackBus.cellBus.lossPower) ;
  connect(gainT.u, stackBus.cellBus.T) ;
end BusTranscription;

model CCCVcharger
  "Charger with constant current - constant voltage characteristic"
  extends Modelica.Electrical.Analog.Interfaces.OnePort;
  parameter SI.Current I "Constant charge current";
  parameter SI.Time startTime=0 "Start time of charging";
  parameter SI.Time rampTime=60 "Ramp up charging current";
  parameter SI.Voltage Vend "End of charge voltage";
  Boolean CV(start=false, fixed=true) "Indicates CV charging";
equation
  CV=v>=Vend;
  if CV then
    v=Vend;
  else
    i = -I*(if time<startTime then 0 else min(1,(time - startTime)/rampTime));
  end if;
end CCCVcharger;

block Impedance "Calculate complex impedance"
  extends Blocks.Icons.Block;
  import Modelica.Constants.pi;
  import Modelica.ComplexMath.sum;
  parameter Modelica.Electrical.Batteries.ParameterRecords.TransientData.CellData cellData "Transient cell data";
  Blocks.Interfaces.RealInput f(unit="Hz") "Frequency";
  ComplexBlocks.Interfaces.ComplexOutput z(re(unit="Ohm"), im(unit="Ohm")) "Complex impedance";
equation
  z = Complex(cellData.R0, 0) + sum({1/Complex(1/cellData.rcData[k].R, 2*pi*f*cellData.rcData[k].C) for k in 1:cellData.nRC});
end Impedance;

block PulseSeries "Series of pulses"
  import Modelica.Math.BooleanVectors.oneTrue;
  parameter Real amplitude1= 1 "Amplitude of 1st pulse series";
  parameter Integer n1(min=0)=1 "Number of pulses of 1st series";
  parameter SI.Time T1 "Length of pulses of 1st series";
  parameter SI.Time Tp1 "Pause between pulses of 1st series";
  parameter Real amplitude2=-amplitude1 "Amplitude of 2nd pulse series";
  parameter Integer n2(min=0)=1 "Number of pulses of 2nd series";
  parameter SI.Time T2=T1 "Length of pulses of 2nd series";
  parameter SI.Time Tp2=Tp1 "Pause between pulses of 1st series";
  parameter SI.Time Tp "Pause between the two series";
  extends Modelica.Blocks.Interfaces.SignalSource;
protected
  parameter SI.Time Tstart1[n1]={startTime + (k-1)*(T1 + Tp1) for k in 1:n1};
  parameter SI.Time Tstart2[n1]={startTime + n1*(T1 + Tp1) + Tp + (k-1)*(T2 + Tp2) for k in 1:n2};
  Boolean on1, on2;
equation
  on1 = oneTrue({time >= Tstart1[k] and time < Tstart1[k] + T1 for k in 1:n1});
  on2 = oneTrue({time >= Tstart2[k] and time < Tstart2[k] + T2 for k in 1:n1});
  y= offset + (if on1 then amplitude1 elseif on2 then amplitude2 else 0);
end PulseSeries;

