  connect(airGapDC.pin_en, ground.p) ;
  connect(compoundDCExcitation.pin_sen, pin_en) ;
  connect(compoundDCExcitation.pin_sep, lesigma.n) ;
  connect(compoundDCExcitation.pin_en, groundE.p) ;
