  smpm.is[1:2] = zeros(2);

equation
  connect(star.pin_n, ground.p);
  connect(terminalBox.plug_sn, smpm.plug_sn) ;
  connect(terminalBox.plug_sp, smpm.plug_sp) ;
  connect(quadraticSpeedDependentTorque.flange, inertiaLoad.flange_b);
  connect(star.plug_p, signalVoltage.plug_n) ;
  connect(currentSensor.plug_n, terminalBox.plugSupply) ;
  connect(id.y, dqCurrentController.id) ;
  connect(iq.y, dqCurrentController.iq) ;
  connect(dqCurrentController.y, signalVoltage.v);
  connect(currentSensor.i, dqCurrentController.iActual) ;
  connect(inertiaLoad.flange_a, multiSensor.flange_b);
  connect(multiSensor.flange_a, smpm.flange);
  connect(rotorDisplacementAngle.flange, smpm.flange) ;
  connect(rotorDisplacementAngle.plug_p, smpm.plug_sp) ;
  connect(rotorDisplacementAngle.plug_n, smpm.plug_sn) ;
  connect(voltageQuasiRMSSensor.plug_p, currentSensor.plug_n) ;
  connect(starM.plug_p, voltageQuasiRMSSensor.plug_n) ;
  connect(groundM.p, starM.pin_n) ;
  connect(currentQuasiRMSSensor.plug_n, currentSensor.plug_p) ;
  connect(signalVoltage.plug_p, currentQuasiRMSSensor.plug_p) ;
  connect(smpm.flange, sinCosResolver.flange);
  connect(sinCosResolver.y, sinCosEvaluation.u);
  connect(sinCosEvaluation.phi, dqCurrentController.phi) ;
