partial model PartialBasicDCMachine "Partial model for DC machine"
  parameter SI.Temperature TaOperational(start=293.15)
    "Operational armature temperature" ;
  parameter SI.Voltage VaNominal(start=100)
    "Nominal armature voltage" ;
  parameter SI.Current IaNominal(start=100)
    "Nominal armature current (>0..Motor, <0..Generator)";
  parameter SI.AngularVelocity wNominal(displayUnit="rev/min",
      start=1425*2*pi/60) "Nominal speed";
  parameter SI.Temperature TaNominal(start=293.15)
    "Nominal armature temperature";
  parameter SI.Resistance Ra(start=0.05)
    "Armature resistance at TaRef";
  parameter SI.Temperature TaRef(start=293.15)
    "Reference temperature of armature resistance";
  parameter Machines.Thermal.LinearTemperatureCoefficient20 alpha20a(start=0)
    "Temperature coefficient of armature resistance";
  parameter SI.Inductance La(start=0.0015)
    "Armature inductance";
  extends PartialBasicMachine(
    Jr(start=0.15),
    frictionParameters(wRef=wNominal),
    friction(final useHeatPort=true));
  parameter Machines.Losses.CoreParameters coreParameters(
    final m=1,
    VRef=ViNominal,
    wRef=wNominal) "Armature core loss parameter record";
  parameter Machines.Losses.StrayLoadParameters strayLoadParameters(IRef=
        IaNominal, wRef=wNominal) "Stray load loss parameter record";
  parameter Machines.Losses.BrushParameters brushParameters(ILinear=0.01*
        IaNominal) "Brush loss parameter record";
  replaceable output
    Machines.Interfaces.DCMachines.PartialPowerBalanceDCMachines powerBalance(
    final powerArmature=va*ia,
    final powerMechanical=wMechanical*tauShaft,
    final powerInertiaStator=inertiaStator.J*inertiaStator.a*inertiaStator.w,
    final powerInertiaRotor=inertiaRotor.J*inertiaRotor.a*inertiaRotor.w,
    final lossPowerArmature=ra.LossPower,
    final lossPowerCore=core.lossPower,
    final lossPowerStrayLoad=strayLoad.lossPower,
    final lossPowerFriction=friction.lossPower,
    final lossPowerBrush=brush.lossPower) "Power balance";

  output SI.Voltage va=pin_ap.v - pin_an.v "Armature voltage";
  output SI.Current ia(start=0) = pin_ap.i "Armature current";
  Modelica.Electrical.Analog.Interfaces.PositivePin pin_ap
    "Positive armature pin" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin pin_an
    "Negative armature pin" ;
  Modelica.Electrical.Analog.Basic.Resistor ra(
    final R=Ra,
    final T_ref=TaRef,
    final alpha=Machines.Thermal.convertAlpha(alpha20a, TaRef),
    final useHeatPort=true) ;
  Machines.BasicMachines.Components.InductorDC la(final L=La, final quasiStatic=
       quasiStatic);
  Machines.Losses.DCMachines.Brush brush(final brushParameters=brushParameters,
      final useHeatPort=true) ;
  Machines.Losses.DCMachines.Core core(final coreParameters=coreParameters,
      final useHeatPort=true);
  Machines.Losses.DCMachines.StrayLoad strayLoad(final strayLoadParameters=
        strayLoadParameters, final useHeatPort=true);
  replaceable Machines.Interfaces.DCMachines.PartialThermalPortDCMachines thermalPort if
    useThermalPort;
  replaceable Machines.Interfaces.DCMachines.PartialThermalAmbientDCMachines thermalAmbient(final
      useTemperatureInputs=false, final Ta=TaOperational) if not useThermalPort;
protected
  constant Real pi = Modelica.Constants.pi;
  constant Boolean quasiStatic=false "No electrical transients if true";
  parameter SI.Voltage ViNominal "Nominal induced Voltage";
  parameter SI.MagneticFlux psi_eNominal
    "Nominal magnetic flux";
  parameter Real turnsRatio=ViNominal/(wNominal*psi_eNominal)
    "Ratio of armature turns over number of turns of the excitation winding";
  replaceable Machines.Interfaces.DCMachines.PartialThermalPortDCMachines internalThermalPort;
equation
  assert(ViNominal > Modelica.Constants.eps,
    "VaNominal has to be > (Ra[+Rse])*IaNominal");
  connect(la.p, ra.n);
  connect(brush.n, pin_an) ;
  connect(pin_ap, strayLoad.p) ;
  connect(strayLoad.n, ra.p) ;
  connect(strayLoad.support, internalSupport) ;
  connect(la.p, core.p) ;
  connect(core.n, brush.p) ;
  connect(core.heatPort, internalThermalPort.heatPortCore) ;
  connect(brush.heatPort, internalThermalPort.heatPortBrush) ;
  connect(strayLoad.heatPort, internalThermalPort.heatPortStrayLoad);
  connect(friction.heatPort, internalThermalPort.heatPortFriction);
  connect(ra.heatPort, internalThermalPort.heatPortArmature) ;
  connect(inertiaRotor.flange_b, strayLoad.flange) ;
  connect(thermalAmbient.thermalPort, internalThermalPort) ;
  connect(internalThermalPort, thermalPort);
end PartialBasicDCMachine;

partial model PartialBasicInductionMachine
  "Partial model for induction machine"
  final parameter Integer m=3 "Number of phases" ;
  parameter Integer p(min=1, start=2) "Number of pole pairs (Integer)";
  parameter SI.Frequency fsNominal(start=50)
    "Nominal frequency";
  parameter SI.Temperature TsOperational(start=293.15)
    "Operational temperature of stator resistance" ;
  parameter SI.Resistance Rs(start=0.03)
    "Stator resistance per phase at TRef";
  parameter SI.Temperature TsRef(start=293.15)
    "Reference temperature of stator resistance";
  parameter Machines.Thermal.LinearTemperatureCoefficient20 alpha20s(start=0)
    "Temperature coefficient of stator resistance at 20 degC";
  parameter SI.Inductance Lszero=Lssigma
    "Stator zero sequence inductance";
  parameter SI.Inductance Lssigma(start=3*(1 - sqrt(1 -
        0.0667))/(2*pi*fsNominal)) "Stator stray inductance per phase";
  extends PartialBasicMachine(
    Jr(start=0.29),
    frictionParameters(wRef=2*pi*fsNominal/p),
    friction(final useHeatPort=true));
  parameter Machines.Losses.CoreParameters statorCoreParameters(
    final m=3,
    VRef(start=100),
    wRef=2*pi*fsNominal)
    "Stator core loss parameter record; all parameters refer to stator side";
  parameter Machines.Losses.StrayLoadParameters strayLoadParameters(IRef(start=
          100), wRef=2*pi*fsNominal/p) "Stray load loss parameter record";
  replaceable output
    Machines.Interfaces.InductionMachines.PartialPowerBalanceInductionMachines powerBalance(
    final powerStator=Machines.SpacePhasors.Functions.activePower(vs, is),
    final powerMechanical=wMechanical*tauShaft,
    final powerInertiaStator=inertiaStator.J*inertiaStator.a*inertiaStator.w,
    final powerInertiaRotor=inertiaRotor.J*inertiaRotor.a*inertiaRotor.w,
    final lossPowerStatorWinding=sum(rs.resistor.LossPower),
    final lossPowerStatorCore=statorCore.lossPower,
    final lossPowerStrayLoad=strayLoad.lossPower,
    final lossPowerFriction=friction.lossPower) "Power balance";

  output SI.Voltage vs[m]=plug_sp.pin.v - plug_sn.pin.v
    "Stator instantaneous voltages";
  output SI.Current is[m]=plug_sp.pin.i
    "Stator instantaneous currents";
  output SI.Current i_0_s(stateSelect=StateSelect.prefer)=
    spacePhasorS.zero.i "Stator zero-sequence current";
  // to be defined in model that extends from this partial (since airgap isn't included here)
  input SI.Current idq_ss[2]
    "Stator space phasor current / stator fixed frame";
  input SI.Current idq_sr[2](each stateSelect=StateSelect.prefer)
    "Stator space phasor current / rotor fixed frame";
  input SI.Current idq_rs[2]
    "Rotor space phasor current / stator fixed frame";
  input SI.Current idq_rr[2](each stateSelect=StateSelect.prefer)
    "Rotor space phasor current / rotor fixed frame";
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_sp(final m=m)
    "Positive stator plug" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_sn(final m=m)
    "Negative stator plug" ;
  Modelica.Electrical.Polyphase.Basic.Resistor rs(
    final m=m,
    final R=fill(Rs, m),
    final T_ref=fill(TsRef, m),
    final alpha=fill(Machines.Thermal.convertAlpha(alpha20s, TsRef), m),
    final useHeatPort=true,
    final T=fill(TsRef, m)) ;
  Machines.BasicMachines.Components.Inductor lssigma(final L=fill(Lssigma, 2));
  Modelica.Electrical.Analog.Basic.Inductor lszero(final L=Lszero);
  Machines.Losses.InductionMachines.Core statorCore(
    final coreParameters=statorCoreParameters,
    final useHeatPort=true,
    final turnsRatio=1) ;
  Machines.SpacePhasors.Components.SpacePhasor spacePhasorS(final turnsRatio=1);
  Machines.Losses.InductionMachines.StrayLoad strayLoad(
    final strayLoadParameters=strayLoadParameters,
    final useHeatPort=true,
    final m=m) ;
  replaceable
    Machines.Interfaces.InductionMachines.PartialThermalPortInductionMachines thermalPort(final m=m) if
       useThermalPort;
  replaceable
