model CurrentQuasiRMSSensor "Length of space phasor -> RMS current"
  extends Modelica.Icons.RoundSensor;
  constant Integer m(final min=1) = 3 "Number of phases";
  Modelica.Blocks.Interfaces.RealOutput I(final quantity="ElectricCurrent",
      final unit="A") ;
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_p(final m=m);
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_n(final m=m);
  Modelica.Electrical.Polyphase.Sensors.CurrentSensor CurrentSensor1(
      final m=m) ;
  Modelica.Blocks.Math.Gain Gain1(final k=1/sqrt(2)) ;
  Machines.SpacePhasors.Blocks.ToSpacePhasor ToSpacePhasor1(m=m) ;
  Machines.SpacePhasors.Blocks.ToPolar ToPolar1 ;
equation
  connect(plug_p, CurrentSensor1.plug_p) ;
  connect(CurrentSensor1.plug_n, plug_n);
  connect(CurrentSensor1.i, ToSpacePhasor1.u) ;
  connect(ToSpacePhasor1.y, ToPolar1.u) ;
  connect(ToPolar1.y[1], Gain1.u) ;
  connect(Gain1.y, I) ;
end CurrentQuasiRMSSensor;

model ElectricalPowerSensor "Instantaneous power from space phasors"
  extends Modelica.Icons.RoundSensor;
  constant Integer m(final min=1) = 3 "Number of phases";
  Modelica.Blocks.Interfaces.RealOutput P(final quantity="Power", final
      unit="W") ;
  Modelica.Blocks.Interfaces.RealOutput Q(final quantity="Power", final
      unit="var") ;
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_p(final m=m);
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_ni(final m=m);
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_nv(final m=m);
protected
  SI.Voltage v_[2];
  SI.Current i_[2];
equation
  plug_p.pin.v = plug_ni.pin.v;
  plug_p.pin.i + plug_ni.pin.i = zeros(m);
  plug_nv.pin.i = zeros(m);
  v_ = Machines.SpacePhasors.Functions.ToSpacePhasor(plug_p.pin.v - plug_nv.pin.v);
  i_ = Machines.SpacePhasors.Functions.ToSpacePhasor(plug_p.pin.i);
  2/3*P = +v_[1]*i_[1] + v_[2]*i_[2];
  2/3*Q = -v_[1]*i_[2] + v_[2]*i_[1];
end ElectricalPowerSensor;

model HallSensor "Hall sensor"
  import Modelica.Constants.pi;
  extends
    Modelica.Mechanics.Rotational.Interfaces.PartialElementaryOneFlangeAndSupport2;
  parameter Integer p(final min=1, start=2) "Number of pole pairs";
  parameter SI.Angle phi0=-pi/p "Initial mechanical angle";
  Modelica.Blocks.Interfaces.RealOutput y(
    quantity="Angle",
    final unit="rad",
    displayUnit="deg") "\"Electrical angle\"";
equation
  flange.tau=0;
  y=rem((flange.phi - phi_support - phi0)*p, 2*pi);
end HallSensor;

model MechanicalPowerSensor "Mechanical power = torque x speed"
  extends Modelica.Icons.RoundSensor;
  extends Modelica.Mechanics.Rotational.Interfaces.PartialTwoFlanges;
  parameter Boolean useSupport=false "Use support or fixed housing";
  Modelica.Blocks.Interfaces.RealOutput P(final quantity="Power", final
      unit="W") ;
  Modelica.Mechanics.Rotational.Sensors.TorqueSensor torqueSensor;
  Modelica.Blocks.Math.Product product ;
  Modelica.Mechanics.Rotational.Sensors.RelSpeedSensor relSpeedSensor;
  Modelica.Mechanics.Rotational.Components.Fixed fixed if (not useSupport);
  Modelica.Mechanics.Rotational.Interfaces.Flange_a support if useSupport
    "Support at which the reaction torque is acting" ;
equation
  connect(flange_a, torqueSensor.flange_a) ;
  connect(torqueSensor.flange_b, flange_b);
  connect(flange_a, relSpeedSensor.flange_b) ;
  connect(relSpeedSensor.flange_a, fixed.flange) ;
  connect(relSpeedSensor.flange_a, support) ;
  connect(relSpeedSensor.w_rel, product.u1) ;
  connect(torqueSensor.tau, product.u2) ;
  connect(product.y, P) ;
end MechanicalPowerSensor;

model RotorDisplacementAngle "Rotor lagging angle"
  parameter Integer m=3 "Number of phases" ;
  parameter Integer p(min=1) "Number of pole pairs";
  parameter Boolean positiveRange=false "Use only positive output range, if true";
  parameter Real threshold(final min=0)=0 "Below threshold the voltage is considered as zero";
  parameter Boolean useSupport=false "Use support or fixed housing";
  Modelica.Blocks.Interfaces.RealOutput rotorDisplacementAngle(final
      quantity="Angle", final unit="rad") ;
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_p(final m=m);
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_n(final m=m);
  Modelica.Electrical.Polyphase.Sensors.VoltageSensor VoltageSensor1(
      final m=m) ;
  SpacePhasors.Blocks.ToSpacePhasor ToSpacePhasorVS(final m=m) ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a flange ;
  Modelica.Mechanics.Rotational.Sensors.RelAngleSensor relativeAngleSensor;
  Modelica.Blocks.Sources.Constant constant_(final k=Modelica.Constants.pi/
        2) ;
  Modelica.Blocks.Math.Add add(final k2=1, final k1=p) ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.Rotator rotatorVS2R;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.ToPolar ToPolarVSR;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a support if useSupport
    "Support at which the reaction torque is acting" ;
  Modelica.Mechanics.Rotational.Components.Fixed fixed if (not useSupport);
  Blocks.Math.WrapAngle wrapAngle(final positiveRange=positiveRange);
  SpacePhasors.Blocks.LessThreshold lessThreshold(final threshold=threshold);
equation
  connect(plug_p, VoltageSensor1.plug_p) ;
  connect(plug_n, VoltageSensor1.plug_n) ;
  connect(relativeAngleSensor.flange_b, flange);
  connect(relativeAngleSensor.flange_a, support) ;
  connect(relativeAngleSensor.flange_a, fixed.flange) ;
  connect(relativeAngleSensor.phi_rel, add.u1) ;
  connect(constant_.y, add.u2) ;
  connect(VoltageSensor1.v, ToSpacePhasorVS.u) ;
  connect(ToSpacePhasorVS.y, rotatorVS2R.u) ;
  connect(rotatorVS2R.y, ToPolarVSR.u) ;
  connect(add.y, rotatorVS2R.angle) ;
  connect(wrapAngle.y, rotorDisplacementAngle) ;
  connect(ToPolarVSR.y, lessThreshold.u);
  connect(lessThreshold.y, wrapAngle.u);
end RotorDisplacementAngle;

model SinCosResolver "Sin-Cos-Resolver"
  import Modelica.Constants.pi;
  extends
    Modelica.Mechanics.Rotational.Interfaces.PartialElementaryOneFlangeAndSupport2;
  parameter Integer p(final min=1, start=2) "Number of pole pairs";
  parameter Real amplitude=1 "Amplitude of signals";
  parameter Real offset=1.5 "Offset of signals";
  parameter SI.Angle phi0=-pi/p "Initial mechanical angle";
  Modelica.Blocks.Interfaces.RealOutput y[4] "Track signals";
equation
  flange.tau=0;
  y[1] = offset + amplitude*cos(p*(flange.phi - phi_support - phi0));
  y[2] = offset - amplitude*cos(p*(flange.phi - phi_support - phi0));
  y[3] = offset + amplitude*sin(p*(flange.phi - phi_support - phi0));
  y[4] = offset - amplitude*sin(p*(flange.phi - phi_support - phi0));
end SinCosResolver;

