package Constants "Material Constants"
  extends Modelica.Icons.Package;
  constant SI.LinearTemperatureCoefficient alpha20Zero=0
    "Not temperature dependent";
  constant SI.LinearTemperatureCoefficient alpha20Aluminium=
      4.000e-3 "Aluminium";
  constant SI.LinearTemperatureCoefficient alpha20Brass=
      1.100e-3 "Brass";
  constant SI.LinearTemperatureCoefficient alpha20Bronze=
      0.800e-3 "Bronze";
  constant SI.LinearTemperatureCoefficient alpha20Copper=
      3.920e-3 "Copper";
end Constants;

function convertAlpha
  "Converts alpha from temperature 1 (default 20 degC) to temperature 2"
  extends Modelica.Icons.Function;
  input SI.LinearTemperatureCoefficient alpha1
    "Temperature coefficient at temperature 1 (default: 20 degC)";
  input SI.Temperature T2 "Temperature 2";
  input SI.Temperature T1=293.15
    "Temperature 1 (default: 20 degC)";
  output SI.LinearTemperatureCoefficient alpha2
    "Temperature coefficient at TRef";
algorithm
  alpha2 := alpha1/(1 + alpha1*(T2 - T1));
end convertAlpha;

function convertResistance
  "Converts resistance from reference temperature to an actual temperature"
  extends Modelica.Icons.Function;
  input SI.Resistance RRef "Resistance at TRef";
  input SI.Temperature TRef "Reference temperature";
  input SI.LinearTemperatureCoefficient alpha20
    "Temperature coefficient at 20 degC";
  input SI.Temperature T "Actual temperature";
  output SI.Resistance R "Actual resistance at T";
algorithm
  R := RRef*(1 + Machines.Thermal.convertAlpha(alpha20, TRef)*(T - TRef));
end convertResistance;

