model DQCurrentController
  "Current controller in dq coordinate system"
  import Modelica.Constants.pi;
  constant Integer m=3 "Number of phases";
  parameter Integer p "Number of pole pairs";
  parameter Boolean useRMS=true "If true, inputs dq are multiplied by sqrt(2)";
  parameter SI.Frequency fsNominal "Nominal frequency";
  parameter SI.Voltage VsOpenCircuit
    "Open circuit RMS voltage per phase @ fsNominal";
  parameter SI.Resistance Rs "Stator resistance per phase";
  parameter SI.Inductance Ld "Inductance in d-axis";
  parameter SI.Inductance Lq "Inductance in q-axis";
  //Decoupling
  parameter Boolean decoupling=false "Use decoupling network";
  final parameter SI.MagneticFlux psiM=sqrt(2)*VsOpenCircuit/
      (2*pi*fsNominal) "Approximation of magnetic flux linkage";
  SI.AngularVelocity omega=p*der(phi);
  SI.Voltage Vd=sqrt(2)*(Rs*id - omega*Lq*iq);
  SI.Voltage Vq=sqrt(2)*(Rs*iq + omega*Ld*id) + omega*psiM;
  extends Modelica.Blocks.Interfaces.MO(final nout=m);
  Modelica.Blocks.Interfaces.RealInput id "Reference of d-current";
  Modelica.Blocks.Interfaces.RealInput iq "Reference of q-current";
  Modelica.Blocks.Interfaces.RealInput phi(unit="rad") "Rotor angle";
  Modelica.Blocks.Interfaces.RealInput iActual[m](each unit="A")
    "Measured three-phase currents" ;
  Machines.Utilities.FromDQ fromDQ(final p=p, final m=m);
  Machines.Utilities.ToDQ toDQ(final p=p, final m=m) ;
  Modelica.Blocks.Math.Gain toPeak_d(final k=if useRMS then sqrt(2) else 1);
  Modelica.Blocks.Math.Gain toPeak_q(final k=if useRMS then sqrt(2) else 1);
  Modelica.Blocks.Math.Feedback feedback_d;
  Modelica.Blocks.Math.Feedback feedback_q;
  Modelica.Blocks.Continuous.PI PI_d(
    final k=unitResistance/Rs,
    final T=Ld/Rs,
    initType=Modelica.Blocks.Types.Init.InitialOutput);
  Modelica.Blocks.Continuous.PI PI_q(
    final k=unitResistance/Rs,
    final T=Lq/Rs,
    initType=Modelica.Blocks.Types.Init.InitialOutput);
  Modelica.Blocks.Math.Add add[2](final k1=fill(+1, 2), final k2=fill(if
        decoupling then +1 else 0, 2));
  Modelica.Blocks.Sources.RealExpression deCoupling[2](y={Vd,Vq});
protected
  constant SI.Resistance unitResistance=1;
equation
  connect(fromDQ.y, y) ;
  connect(phi, fromDQ.phi) ;
  connect(iActual, toDQ.u) ;
  connect(phi, toDQ.phi) ;
  connect(toPeak_d.u, id);
  connect(toPeak_q.u, iq) ;
  connect(toPeak_q.y, feedback_q.u1) ;
  connect(toPeak_d.y, feedback_d.u1) ;
  connect(feedback_d.y, PI_d.u) ;
  connect(feedback_q.y, PI_q.u) ;
  connect(toDQ.y[1], feedback_d.u2) ;

  connect(toDQ.y[2], feedback_q.u2) ;

  connect(add.y, fromDQ.u) ;
  connect(PI_d.y, add[1].u1) ;
  connect(PI_q.y, add[2].u1) ;
  connect(deCoupling.y, add.u2) ;
end DQCurrentController;

model DQToThreePhase "Transforms dq to three-phase"
  parameter Integer m=3 "Number of phases" ;
  parameter Integer p "Number of pole pairs";
  parameter Boolean useRMS=true "If true, inputs dq are multiplied by sqrt(2)";
  extends Modelica.Blocks.Interfaces.MO(final nout=m);
  Modelica.Blocks.Interfaces.RealInput d "d-component";
  Modelica.Blocks.Interfaces.RealInput q "q-component";
  Modelica.Blocks.Interfaces.RealInput phi(unit="rad") "Rotor angle";
  Modelica.Blocks.Math.Gain toPeak_d(k=if useRMS then sqrt(2) else 1);
  Modelica.Blocks.Math.Gain toPeak_q(k=if useRMS then sqrt(2) else 1);
  Modelica.Blocks.Math.Gain toGamma(k=-p) ;
  Machines.SpacePhasors.Blocks.Rotator rotator;
  Modelica.Blocks.Sources.Constant i0(k=0) ;
  Machines.SpacePhasors.Blocks.FromSpacePhasor fromSpacePhasor(final m=m);
equation
  connect(q, toPeak_q.u);
  connect(phi, toGamma.u);
  connect(rotator.angle, toGamma.y);
  connect(rotator.y, fromSpacePhasor.u);
  connect(toPeak_d.u, d);
  connect(toPeak_d.y, rotator.u[1]) ;
  connect(toPeak_q.y, rotator.u[2]) ;
  connect(i0.y, fromSpacePhasor.zero) ;
  connect(fromSpacePhasor.y, y) ;
end DQToThreePhase;

block FromDQ
  "Transform rotor fixed space phasor to instantaneous stator quantities"
  extends Modelica.Blocks.Interfaces.MIMO(final nin=2, final nout=m);
  parameter Integer m(min=1) = 3 "Number of phases" ;
  parameter Integer p "Number of pole pairs";
  Modelica.Blocks.Math.Gain toGamma(final k=-p) ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.Rotator rotator;
  Modelica.Blocks.Sources.Constant i0(final k=0) ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.FromSpacePhasor fromSpacePhasor(final m=m);
  Modelica.Blocks.Interfaces.RealInput phi(unit="rad") ;
equation
  connect(phi, toGamma.u);
  connect(rotator.angle, toGamma.y);
  connect(rotator.y, fromSpacePhasor.u);
  connect(i0.y, fromSpacePhasor.zero) ;
  connect(u, rotator.u) ;
  connect(fromSpacePhasor.y, y) ;
end FromDQ;

model MultiTerminalBox "Terminal box Y/D-connection"
  parameter Integer m(min=1) = 3 "Number of phases" ;
  final parameter Integer mSystems=
      Modelica.Electrical.Polyphase.Functions.numberOfSymmetricBaseSystems(
      m) "Number of symmetric base systems";
  final parameter Integer mBasic=integer(m/mSystems) "Number of phases of basic system";
  parameter String terminalConnection(start="Y") "Choose \"Y\" for star or \"D\" for delta connection";
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_sp(final m=m)
    "To be connected with positive stator plug" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_sn(final m=m)
    "To be connected with negative stator plug" ;
  Polyphase.Basic.MultiStar multiStar(final m=m) if (terminalConnection
     <> "D") ;
  Polyphase.Basic.MultiDelta multiDelta(final m=m) if (terminalConnection
     == "D") ;
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plugSupply(final m=
       m) "To be connected with grid" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug starpoint(final m=
        mSystems) if (terminalConnection <> "D") "Star point" ;
equation
  connect(plug_sn, multiStar.plug_p);
  connect(plug_sn, multiDelta.plug_n) ;
  connect(multiDelta.plug_p, plug_sp) ;
  connect(plug_sp, plugSupply) ;
  connect(starpoint, multiStar.starpoints) ;
end MultiTerminalBox;

