model RampedRheostat "Rheostat with linearly decreasing resistance"
  parameter Integer m=3 "Number of phases" ;
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_p(final m=m)
    "To positive rotor plug" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_n(final m=m)
    "To negative rotor plug" ;
  parameter SI.Resistance RStart "Starting resistance";
  parameter SI.Time tStart
    "Time instance of reducing the rheostat";
  parameter SI.Time tRamp "Duration of ramp";
  Modelica.Electrical.Polyphase.Basic.Star star(final m=m) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Electrical.Polyphase.Basic.VariableResistor rheostat(final m=m);
  Modelica.Blocks.Sources.Ramp ramp[m](
    final height=fill(-RStart, m),
    final duration=fill(tRamp, m),
    final offset=fill(RStart, m),
    final startTime=fill(tStart, m)) ;
equation
  connect(plug_p, rheostat.plug_p) ;
  connect(rheostat.plug_n, plug_n) ;
  connect(rheostat.R, ramp.y) ;
  connect(rheostat.plug_n, star.plug_p) ;
  connect(star.pin_n, ground.p) ;
end RampedRheostat;

block SinCosEvaluation "Evaluation of the signals of a sin-cos-resolver"
  extends Modelica.Blocks.Icons.Block;
  Blocks.Interfaces.RealInput u[4] "Signal from sin-cos-resolver";
  Blocks.Math.Feedback feedbackCos;
  Blocks.Math.Feedback feedbackSin;
  SpacePhasors.Blocks.Rotator rotator;
  Blocks.Continuous.Integrator integrator(final k=1e6);
  Blocks.Continuous.Der der1;
  Blocks.Interfaces.RealOutput phi(unit="rad") "Angle";
  Blocks.Interfaces.RealOutput w(unit="rad/s") "Angular velocity";
equation
  connect(u[1], feedbackCos.u1) ;
  connect(u[2], feedbackCos.u2);
  connect(u[3], feedbackSin.u1) ;
  connect(u[4], feedbackSin.u2) ;
  connect(feedbackCos.y, rotator.u[1]) ;
  connect(feedbackSin.y, rotator.u[2]) ;
  connect(rotator.y[2], integrator.u);
  connect(integrator.y, rotator.angle) ;
  connect(integrator.y, der1.u) ;
  connect(integrator.y, phi);
  connect(der1.y, w);
end SinCosEvaluation;

model SwitchedRheostat "Rheostat which is shortened after a given time"
  parameter Integer m=3 "Number of phases" ;
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_p(final m=m)
    "To positive rotor plug" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_n(final m=m)
    "To negative rotor plug" ;
  parameter SI.Resistance RStart "Starting resistance";
  parameter SI.Time tStart
    "Duration of switching on the starting resistor";
  Modelica.Electrical.Polyphase.Basic.Star star(final m=m) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Electrical.Polyphase.Ideal.IdealCommutingSwitch
    idealCommutingSwitch(
    final m=m,
    Ron=fill(1e-5, m),
    Goff=fill(1e-5, m)) ;
  Modelica.Electrical.Polyphase.Basic.Resistor rheostat(final m=m, final R=
       fill(RStart, m)) ;
  Modelica.Electrical.Polyphase.Basic.Star starRheostat(final m=m);
  Modelica.Blocks.Sources.BooleanStep booleanStep[m](final startTime=fill(
        tStart, m), final startValue=fill(false, m)) ;
equation
  connect(plug_p, idealCommutingSwitch.plug_p) ;
  connect(idealCommutingSwitch.plug_n2, plug_n) ;
  connect(rheostat.plug_p, idealCommutingSwitch.plug_n1) ;
  connect(idealCommutingSwitch.plug_n2, star.plug_p) ;
  connect(rheostat.plug_n, starRheostat.plug_p) ;
  connect(starRheostat.pin_n, star.pin_n) ;
  connect(star.pin_n, ground.p) ;
  connect(booleanStep.y, idealCommutingSwitch.control) ;
end SwitchedRheostat;

model SwitchYD "Y-D-switch"
  parameter Integer m=3 "Number of phases" ;
  parameter SI.Resistance Ron=1e-5 "Closed switch resistance";
  parameter SI.Conductance Goff=1e-5 "Opened switch conductance";
  parameter SI.Time delayTime(final min=0)=0 "Time delay";
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plugSupply(final m=
       m) "To grid" ;
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_sp(final m=m)
    "To positive stator plug" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_sn(final m=m)
    "To negative stator plug" ;
  Modelica.Electrical.Polyphase.Basic.Star star(final m=m) ;
  Modelica.Electrical.Polyphase.Basic.Delta delta(final m=m) ;
  Polyphase.Ideal.IdealClosingSwitch idealCloser(
    final m=m,
    Ron=fill(Ron, m),
    Goff=fill(Goff, m));
  Modelica.Blocks.Interfaces.BooleanInput control[m] ;
  Polyphase.Ideal.IdealOpeningSwitch idealOpener(
    final m=m,
    Ron=fill(Ron, m),
    Goff=fill(Goff, m));
  Blocks.Logical.LogicalDelay logicalDelay[m](delayTime=fill(delayTime, m));
equation
  connect(delta.plug_p, plugSupply) ;
  connect(delta.plug_p, plug_sp) ;
  connect(idealCloser.plug_p, plug_sn) ;
  connect(idealCloser.plug_n, delta.plug_n);
  connect(idealOpener.plug_p, plug_sn);
  connect(idealOpener.plug_n, star.plug_p);
  connect(control, logicalDelay.u);
  connect(logicalDelay.y1, idealOpener.control);
  connect(logicalDelay.y2, idealCloser.control);
