model MultiDelta
  "Delta (polygon) connection of polyphase systems consisting of multiple base systems"
  import Modelica.Electrical.Polyphase.Functions.numberOfSymmetricBaseSystems;
  parameter Integer m(final min=2) = 3 "Number of phases" ;
  parameter Integer kPolygon(final min=1)=1 "Alternative of polygon";
  final parameter Integer mSystems=numberOfSymmetricBaseSystems(m) "Number of base systems";
  final parameter Integer mBasic=integer(m/mSystems) "Phase number of base systems";
  Polyphase.Interfaces.PositivePlug plug_p(final m=m);
  Polyphase.Interfaces.NegativePlug plug_n(final m=m);
protected
  parameter Integer kP=if (mBasic<=2 or kPolygon<1 or kPolygon>integer(mBasic - 1)/2) then 1 else kPolygon;
equation
  for k in 1:mSystems loop
    for j in 1:(mBasic -kP) loop
      connect(plug_n.pin[(k - 1)*mBasic + j], plug_p.pin[(k - 1)*mBasic + j + kP]);
    end for;
    for j in (mBasic - kP + 1):mBasic loop
      connect(plug_n.pin[(k - 1)*mBasic + j], plug_p.pin[(k - 2)*mBasic + j + kP]);
    end for;
  end for;
end MultiDelta;

model MultiStar
  "Star connection of polyphase systems consisting of multiple base systems"
  import Modelica.Electrical.Polyphase.Functions.numberOfSymmetricBaseSystems;
  parameter Integer m(final min=1) = 3 "Number of phases" ;
  final parameter Integer mSystems=numberOfSymmetricBaseSystems(m) "Number of base systems";
  final parameter Integer mBasic=integer(m/mSystems) "Phase number of base systems";
  Polyphase.Interfaces.PositivePlug plug_p(final m=m);
  Polyphase.Interfaces.NegativePlug starpoints(final m=mSystems);
equation
  for k in 1:mSystems loop
    for j in 1:mBasic loop
      connect(plug_p.pin[(k - 1)*mBasic + j], starpoints.pin[k]);
    end for;
  end for;
end MultiStar;

model MultiStarResistance "Resistance connection of star points"
  import Modelica.Electrical.Polyphase.Functions.numberOfSymmetricBaseSystems;
  parameter Integer m(final min=2) = 3 "Number of phases" ;
  final parameter Integer mBasic=numberOfSymmetricBaseSystems(m) "Number of symmetric base systems";
  parameter SI.Resistance R=1e6 "Insulation resistance between base systems";
  Polyphase.Interfaces.PositivePlug plug(m=m);
  Polyphase.Basic.MultiStar multiStar(m=m) ;
  Polyphase.Basic.Resistor resistor(m=mBasic, R=fill(R, mBasic));
  Polyphase.Basic.Star star(m=mBasic) ;
  Modelica.Electrical.Analog.Interfaces.NegativePin pin ;
equation
  connect(plug, multiStar.plug_p) ;
  connect(multiStar.starpoints, resistor.plug_p) ;
  connect(resistor.plug_n, star.plug_p) ;
