model PolyphaseRectifier "Demonstrate a polyphase diode rectifier"
  extends Icons.Example;
  parameter Utilities.PolyphaseRectifierData data;
  Sources.SineVoltage sineVoltage(
    m=data.m,
    V=sqrt(2)*fill(data.VrmsY, data.m),
    f=fill(data.f, data.m)) ;
  Basic.MultiStarResistance multiStar(m=data.m, R=data.RGnd);
  Analog.Basic.Resistor resistor2ground(R=data.RGnd);
  Analog.Basic.Ground groundAC;
  Utilities.AnalysatorAC analysatorAC(m=data.m, f=data.f) ;
  Basic.SplitToSubsystems splitToSubsystems(m=data.m);
  Ideal.IdealDiode diode1[data.mSystems](
    each m=data.mBasic,
    each Ron=fill(1e-6, data.mBasic),
    each Goff=fill(1e-6, data.mBasic),
    each Vknee=fill(0, data.mBasic)) ;
  Ideal.IdealDiode diode2[data.mSystems](
    each m=data.mBasic,
    each Ron=fill(1e-6, data.mBasic),
    each Goff=fill(1e-6, data.mBasic),
    each Vknee=fill(0, data.mBasic)) ;
  Basic.Star star1[data.mSystems](each m=data.mBasic) ;
  Basic.Star star2[data.mSystems](each m=data.mBasic) ;
  Analog.Basic.Resistor resistorDC1[data.mSystems](each R=data.RDC/2);
  Analog.Basic.Inductor inductorDC1[data.mSystems](each i(fixed=true, start=0),
      each L=data.LDC/2);
  Utilities.AnalysatorDC analysatorDC[data.mSystems](each f=data.f);
  Analog.Basic.Resistor resistorDC2[data.mSystems](each R=data.RDC/2) ;
  Analog.Basic.Inductor inductorDC2[data.mSystems](each i(fixed=true, start=0),
      each L=data.LDC/2) ;
  Utilities.AnalysatorDC analysatorDCload(f=data.f);
  Analog.Basic.Resistor loadResistor1(R=data.RLoad/2) ;
  Analog.Basic.Resistor loadResistor2(R=data.RLoad/2) ;
  Analog.Basic.Ground groundDC ;
equation
  for p in 1:data.Par loop
    for s in 1:data.Ser - 1 loop
      connect(inductorDC2[(p - 1)*data.Ser + s].p, inductorDC1[(p - 1)*data.Ser + s + 1].n);
    end for;
    connect(inductorDC1[(p - 1)*data.Ser + 1].n, analysatorDCload.p);
    connect(loadResistor2.n, inductorDC2[p*data.Ser].p);
  end for;
  connect(sineVoltage.plug_n, multiStar.plug);
  connect(star1.plug_p, diode1.plug_n);
  connect(diode2.plug_p, star2.plug_p);
  connect(loadResistor1.n, groundDC.p);
  connect(groundDC.p, loadResistor2.p);
  connect(multiStar.pin, resistor2ground.p);
  connect(resistor2ground.n, groundAC.p);
  connect(diode1.plug_p, diode2.plug_n);
  connect(analysatorAC.plug_p, sineVoltage.plug_p);
  connect(analysatorAC.plug_nv, multiStar.plug);
  connect(analysatorDCload.n, loadResistor1.p);
  connect(loadResistor2.n, analysatorDCload.nv) ;
  connect(analysatorAC.plug_n, splitToSubsystems.plug_p);
  connect(splitToSubsystems.plugs_n, diode1.plug_p);
  connect(star1.pin_n, analysatorDC.p);
  connect(analysatorDC.n, resistorDC1.p);
  connect(resistorDC1.n, inductorDC1.p);
  connect(star2.pin_n, resistorDC2.n);
  connect(resistorDC2.p, inductorDC2.n);
  connect(star2.pin_n, analysatorDC.nv);
end PolyphaseRectifier;

model Rectifier "Test example with polyphase components"
  extends Modelica.Icons.Example;
  import Modelica.Electrical.Polyphase.Functions.factorY2DC;
  final parameter Integer m=3 "Number of phases" ;
  parameter SI.Voltage V=100 "RMS of Star-Voltage";
  parameter SI.Frequency f=50 "Frequency";
  parameter SI.Inductance L=0.0001 "Line Inductance";
  parameter SI.Resistance RL=2 "Load Resistance";
  parameter SI.Capacitance C=0.005 "Total DC-Capacitance";
  parameter SI.Resistance RE=1E6 "Earthing Resistance";
  parameter SI.Resistance Ron=1e-5 "Closed diode resistance";
  parameter SI.Conductance Goff=1e-5
    "Opened diode conductance";
  parameter SI.Voltage Vknee=0 "Threshold diode voltage";
  final parameter SI.Voltage VDC=factorY2DC(m)*V "Estimated average DC voltage";
  final parameter SI.Current IDC=VDC/RL "Estimated average DC current";
  Sources.SineVoltage sineVoltage(
    m=m,
    f=fill(f, m),
    V=sqrt(2)*fill(V, m));
  Basic.Star starS(m=m) ;
  Basic.Inductor supplyL(m=m, L=fill(L, m)) ;
  Ideal.IdealDiode idealDiode1(
    m=m,
    Ron=fill(Ron, m),
    Goff=fill(Goff, m),
    Vknee=fill(Vknee, m)) ;
  Basic.Star star1(m=m) ;
  Ideal.IdealDiode idealDiode2(
    m=m,
    Ron=fill(Ron, m),
    Goff=fill(Goff, m),
    Vknee=fill(Vknee, m)) ;
  Basic.Star star2(m=m) ;
  Modelica.Electrical.Analog.Basic.Resistor loadR(R=RL) ;
  Modelica.Electrical.Analog.Basic.Capacitor cDC1(C=2*C) ;
  Modelica.Electrical.Analog.Basic.Capacitor cDC2(C=2*C) ;
  Modelica.Electrical.Analog.Basic.Ground groundDC ;
  Modelica.Electrical.Machines.Sensors.ElectricalPowerSensor powerSensorSpacePhasor;
  Sensors.AronSensor aronSensor ;
  Sensors.PowerSensor powerSensor(m=m) ;
  Sensors.ReactivePowerSensor reactivePowerSensor ;
initial equation
  cDC1.v = VDC/2;
  cDC2.v = VDC/2;
//supplyL.i[1:m - 1] = zeros(m - 1) "Y-connection";
  supplyL.i[2]=-IDC;
  supplyL.i[3]= IDC;
equation
  connect(cDC1.n, cDC2.p);
  connect(cDC1.n, groundDC.p) ;
  connect(starS.plug_p, sineVoltage.plug_n);
  connect(sineVoltage.plug_p, supplyL.plug_p);
  connect(idealDiode1.plug_n, star1.plug_p);
  connect(idealDiode2.plug_p, star2.plug_p) ;
  connect(star2.pin_n, loadR.n) ;
  connect(star2.pin_n, cDC2.n) ;
  connect(star1.pin_n, loadR.p);
  connect(star1.pin_n, cDC1.p);
  connect(idealDiode1.plug_p, idealDiode2.plug_n);
  connect(supplyL.plug_n, powerSensor.pc);
  connect(powerSensor.nc, powerSensorSpacePhasor.plug_p);
  connect(powerSensorSpacePhasor.plug_ni, aronSensor.plug_p);
  connect(aronSensor.plug_n, reactivePowerSensor.plug_p);
  connect(idealDiode1.plug_p, reactivePowerSensor.plug_n);
  connect(powerSensor.pc, powerSensor.pv);
  connect(starS.plug_p, powerSensor.nv);
  connect(starS.plug_p, powerSensorSpacePhasor.plug_nv);
end Rectifier;

model TestSensors
  extends Modelica.Icons.Example;
  constant Integer m=3 "Number of phases";
  import Modelica.Constants.pi;
  parameter SI.Voltage VRMS=100
    "Nominal RMS voltage per phase";
  parameter SI.Frequency f=50 "Frequency";
  parameter SI.Resistance R=1/sqrt(2) "Load resistance";
  parameter SI.Inductance L=1/sqrt(2)/(2*pi*f) "Load inductance";
  final parameter SI.Impedance Z=sqrt(R^2 + (2*pi*f*L)^2) "Load impedance";
  final parameter SI.Current IRMS=VRMS/Z "Steady state RMS current";
  final parameter SI.ActivePower P=3*R*IRMS^2 "Total active power";
  final parameter SI.ReactivePower Q=3*(2*pi*f*L)*IRMS^2 "Total reactive power";
  final parameter SI.ApparentPower S=3*Z*IRMS^2 "Total apparent power";
  Modelica.Electrical.Polyphase.Sources.SineVoltage sineVoltage(
    final m=m,
    V=fill(sqrt(2)*VRMS, m),
    f=fill(f, m)) ;
  Modelica.Electrical.Polyphase.Basic.Star star(final m=m) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Electrical.Polyphase.Basic.Resistor resistor(m=m, R=fill(R, m));
  Modelica.Electrical.Polyphase.Basic.Inductor inductor(m=m, L=fill(L, m));
  Modelica.Electrical.Polyphase.Basic.Star starLoad(m=m) ;
  Modelica.Electrical.Polyphase.Sensors.CurrentQuasiRMSSensor
    currentQuasiRMSSensor(m=m) ;
  Modelica.Blocks.Math.Feedback feedbackI;
  Modelica.Blocks.Sources.Constant constI(k=IRMS) ;

  Sensors.VoltageQuasiRMSSensor voltageQuasiRMSSensor(m=m) ;
  Modelica.Blocks.Math.Feedback feedbackV;
  Modelica.Blocks.Sources.Constant constV(k=VRMS) ;
  Sensors.PowerSensor powerSensor(m=m) ;
  Modelica.Blocks.Math.Feedback feedbackP;
  Modelica.Blocks.Sources.RealExpression realExpression(y=
        Modelica.Electrical.Polyphase.Functions.activePower(
        voltageQuasiRMSSensor.v, currentQuasiRMSSensor.i)) ;
  Modelica.Electrical.Machines.Sensors.ElectricalPowerSensor powerSensorSpacePhasor;
  Modelica.Blocks.Math.Feedback feedbackSpacePhasor ;
  Sensors.AronSensor aronSensor ;
  Modelica.Blocks.Math.Feedback feedbackAron;
  Sensors.ReactivePowerSensor reactivePowerSensor ;
  Modelica.Blocks.Math.Feedback feedbackQ;
initial equation
  for k in 1:m - 1 loop
    inductor.i[k] = 0;
  end for;

equation
  connect(star.pin_n, ground.p);

  connect(resistor.plug_n, inductor.plug_p) ;
  connect(inductor.plug_n, starLoad.plug_p) ;
  connect(voltageQuasiRMSSensor.plug_n, sineVoltage.plug_n) ;
  connect(voltageQuasiRMSSensor.plug_p, sineVoltage.plug_p) ;
  connect(feedbackV.u1, voltageQuasiRMSSensor.V) ;
  connect(constV.y, feedbackV.u2) ;
  connect(powerSensor.nc, resistor.plug_p) ;
  connect(powerSensor.pc, powerSensor.pv) ;
  connect(powerSensor.nv, starLoad.plug_p) ;
  connect(powerSensor.power, feedbackP.u1) ;
  connect(aronSensor.plug_n, powerSensor.pc);
  connect(sineVoltage.plug_n, star.plug_p);
  connect(feedbackI.u2, constI.y);
  connect(feedbackI.u1, currentQuasiRMSSensor.I);
  connect(currentQuasiRMSSensor.plug_p, sineVoltage.plug_p);
  connect(feedbackP.u2, realExpression.y);
  connect(powerSensorSpacePhasor.plug_p, currentQuasiRMSSensor.plug_n);
  connect(powerSensorSpacePhasor.plug_nv, starLoad.plug_p) ;
  connect(powerSensorSpacePhasor.plug_ni, reactivePowerSensor.plug_p);
  connect(reactivePowerSensor.plug_n, aronSensor.plug_p);
  connect(reactivePowerSensor.reactivePower, feedbackQ.u1);
  connect(powerSensorSpacePhasor.Q, feedbackQ.u2) ;
  connect(aronSensor.power, feedbackAron.u1);
  connect(feedbackSpacePhasor.u1, powerSensorSpacePhasor.P) ;
  connect(realExpression.y, feedbackAron.u2);
  connect(realExpression.y, feedbackSpacePhasor.u2) ;
end TestSensors;

model TransformerYD "Test example with polyphase components"
  extends Modelica.Icons.Example;
  parameter Integer m=3 "Number of phases" ;
  parameter SI.Voltage V=1 "Amplitude of Star-Voltage";
  parameter SI.Frequency f=5 "Frequency";
  parameter SI.Inductance Lm=1 "Transformer main inductance";
  parameter SI.Inductance LT=0.003
    "Transformer stray inductance";
  parameter SI.Resistance RT=0.05 "Transformer resistance";
  parameter SI.Resistance RL=1 "Load Resistance";
  parameter Real nT=1/sqrt((1 - Modelica.Math.cos(2*Modelica.Constants.pi/m))
      ^2 + (Modelica.Math.sin(2*Modelica.Constants.pi/m))^2)
    "Transformer ratio";
  Sources.SineVoltage sineVoltage(
    V=fill(V, m),
    f=fill(f, m),
    m=m) ;
  Basic.Star starS(m=m) ;
  Modelica.Electrical.Analog.Basic.Ground groundS ;
  Ideal.IdealTransformer idealTransformer(
    m=m,
    n=fill(nT, m),
    Lm1=fill(Lm, m)) ;
  Basic.Star starT(m=m) ;
  Basic.Delta deltaT2(m=m) ;
  Modelica.Electrical.Analog.Basic.Ground groundT ;
  Basic.Resistor transformerR(m=m, R=fill(RT/nT^2, m)) ;
  Basic.Inductor transformerL(m=m, L=fill(LT/nT^2, m)) ;
  Basic.Resistor loadR(m=m, R=fill(RL, m)) ;
  Basic.Star starL(m=m) ;
  Modelica.Electrical.Analog.Basic.Ground groundL ;
initial equation
  transformerL.i[1:m] = zeros(m) "D-connection";

equation
  connect(groundS.p, starS.pin_n);
  connect(groundT.p, starT.pin_n);
  connect(starS.plug_p, sineVoltage.plug_n);
  connect(sineVoltage.plug_p, idealTransformer.plug_p1);
  connect(idealTransformer.plug_n1, starT.plug_p);
  connect(idealTransformer.plug_p2, transformerR.plug_p);
  connect(transformerR.plug_n, transformerL.plug_p);
  connect(transformerL.plug_n, deltaT2.plug_p);
  connect(deltaT2.plug_n, idealTransformer.plug_n2);
  connect(deltaT2.plug_p, loadR.plug_p);
  connect(loadR.plug_n, starL.plug_p);
  connect(starL.pin_n, groundL.p);
end TransformerYD;

