    thermalCollector(final m=m) if useHeatPort;
equation
  if not useHeatPort then
    LossPower = sum(diode_p.idealDiode.LossPower) + sum(diode_n.idealDiode.LossPower);
  end if;
  connect(ac, diode_p.plug_p) ;
  connect(diode_p.plug_p, diode_n.plug_n) ;
  connect(diode_p.plug_n, star_p.plug_p) ;
  connect(star_p.pin_n, dc_p) ;
  connect(diode_n.plug_p, star_n.plug_p) ;
  connect(star_n.pin_n, dc_n) ;
  connect(thermalCollector.port_a, diode_n.heatPort) ;
