  QuasiStatic.Polyphase.Basic.PlugToPin_n plugToPin_n2(k=2, m=m) ;
  QuasiStatic.Polyphase.Basic.PlugToPin_n plugToPin_n3(k=3, m=m) ;
  QuasiStatic.SinglePhase.Sensors.CurrentSensor currentSensor0 ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToPolar complexToPolar[m];
equation
  connect(ground.pin, star.pin_n);
  connect(star.plug_p, voltageSource.plug_n);
  connect(voltageSource.plug_p, powerSensor.currentP) ;
  connect(powerSensor.currentN, currentSensor.plug_p);
  connect(powerSensor.voltageP, powerSensor.currentP) ;
  connect(powerSensor.voltageN, star.plug_p) ;
  connect(currentSensor.plug_n, plugToPin_p2.plug_p);
  connect(currentSensor.plug_n, plugToPin_p3.plug_p) ;
  connect(currentSensor.plug_n, plugToPin_p1.plug_p) ;
  connect(plugToPin_p1.pin_p, inductor.pin_p);
  connect(plugToPin_p2.pin_p, capacitor.pin_p);
  connect(plugToPin_p3.pin_p, resistor.pin_p);
  connect(inductor.pin_n, plugToPin_n1.pin_n);
  connect(capacitor.pin_n, plugToPin_n2.pin_n);
  connect(resistor.pin_n, plugToPin_n3.pin_n);
  connect(plugToPin_n1.plug_n, star2.plug_p) ;
  connect(plugToPin_n2.plug_n, star2.plug_p) ;
  connect(plugToPin_n3.plug_n, star2.plug_p) ;
  connect(star2.pin_n, currentSensor0.pin_p);
  connect(currentSensor0.pin_n, star.pin_n);
  connect(currentSensor.i, complexToPolar.u);
end BalancingStar;

model TestSensors
  extends Modelica.Icons.Example;
  constant Integer m=3 "Number of phases";
  import Modelica.Constants.pi;
  parameter SI.Voltage VRMS=100
    "Nominal RMS voltage per phase";
  parameter SI.Frequency f=50 "Frequency";
  parameter SI.Resistance R=1/sqrt(2) "Load resistance";
  parameter SI.Inductance L=1/sqrt(2)/(2*pi*f) "Load inductance";
  final parameter SI.Impedance Z=sqrt(R^2 + (2*pi*f*L)^2) "Load impedance";
  final parameter SI.Current IRMS=VRMS/Z "Steady state RMS current";
  final parameter SI.ActivePower P=3*R*IRMS^2 "Total active power";
  final parameter SI.ReactivePower Q=3*(2*pi*f*L)*IRMS^2 "Total reactive power";
  final parameter SI.ApparentPower S=3*Z*IRMS^2 "Total apparent power";
  Modelica.Electrical.QuasiStatic.Polyphase.Sources.VoltageSource sineVoltage(
    final m=m,
    f=f,
    V=fill(VRMS, m),
    gamma(fixed=true, start=0));
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star star(final m=m) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Resistor resistor(m=m, R_ref=fill(R, m));
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Inductor inductor(m=m, L=fill(L, m));
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star starLoad(m=m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.CurrentQuasiRMSSensor
    currentQuasiRMSSensor(m=m) ;
  Modelica.Blocks.Math.Feedback feedbackI;
  Modelica.Blocks.Sources.Constant constI(k=IRMS) ;

  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.VoltageQuasiRMSSensor voltageQuasiRMSSensor(m=m);
  Modelica.Blocks.Math.Feedback feedbackV;
  Modelica.Blocks.Sources.Constant constV(k=VRMS) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor powerSensor(m=m);
  Modelica.ComplexBlocks.ComplexMath.ComplexToReal complexToReal;
  Modelica.Blocks.Math.Feedback feedbackP;
  Modelica.Blocks.Sources.RealExpression realExpression(y=
    Modelica.Electrical.QuasiStatic.Polyphase.Functions.activePower(
        voltageQuasiRMSSensor.v, currentQuasiRMSSensor.i)) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.AronSensor aronSensor ;
  Modelica.Blocks.Math.Feedback feedbackPAron;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.ReactivePowerSensor
    reactivePowerSensor ;
  Modelica.Blocks.Math.Feedback feedbackQ;
equation

  connect(feedbackV.u1, voltageQuasiRMSSensor.V) ;
  connect(constV.y, feedbackV.u2) ;
  connect(realExpression.y, feedbackP.u2);
  connect(voltageQuasiRMSSensor.plug_p, sineVoltage.plug_p);
  connect(voltageQuasiRMSSensor.plug_n, sineVoltage.plug_n);
  connect(powerSensor.currentP, aronSensor.plug_n);
  connect(powerSensor.currentP, powerSensor.voltageP);
  connect(powerSensor.currentN, resistor.plug_p);
  connect(resistor.plug_n, inductor.plug_p);
  connect(inductor.plug_n, starLoad.plug_p);
  connect(starLoad.plug_p, powerSensor.voltageN);
  connect(star.pin_n, ground.pin);
  connect(sineVoltage.plug_n, star.plug_p);
  connect(powerSensor.apparentPower, complexToReal.u) ;
  connect(complexToReal.re, feedbackP.u1) ;
  connect(feedbackI.u2, constI.y);
  connect(feedbackI.u1, currentQuasiRMSSensor.I);
  connect(currentQuasiRMSSensor.plug_p, sineVoltage.plug_p);
  connect(reactivePowerSensor.plug_n, aronSensor.plug_p);
  connect(currentQuasiRMSSensor.plug_n, reactivePowerSensor.plug_p);
  connect(reactivePowerSensor.reactivePower, feedbackQ.u1);
  connect(aronSensor.activePower, feedbackPAron.u1) ;
  connect(complexToReal.re, feedbackPAron.u2);
  connect(complexToReal.im, feedbackQ.u2) ;
end TestSensors;

model UnsymmetricalLoad "Unsymmetrical three-phase load"
  extends Modelica.Icons.Example;
  import Modelica.ComplexMath.abs;
  output SI.Current i1_d=symmetricalComponents_1.abs_y[1]
    "With neutral, direct component";
  output SI.Current i1_i=symmetricalComponents_1.abs_y[2]
    "With neutral, inverse component";
  output SI.Current i1_0=symmetricalComponents_1.abs_y[3]
    "With neutral, zero component";
  output SI.Current i1_n=abs(currentSensorN.i)
    "With neutral, neutral current";
  output SI.Current i2_d=symmetricalComponents_2.abs_y[1]
    "Without neutral, direct component";
  output SI.Current i2_i=symmetricalComponents_2.abs_y[2]
    "Without neutral, inverse component";
  output SI.Current i2_0=symmetricalComponents_2.abs_y[3]
    "Without neutral, zero component";
  output SI.Voltage v2_n=abs(voltageSensorN.v)
