  SinglePhase.Basic.Resistor resistor1_2(R_ref=100);
  SinglePhase.Basic.Resistor resistor1_3(R_ref=60);
  SinglePhase.Basic.Inductor inductor1_2(L=0.25);
  SinglePhase.Basic.Capacitor capacitor1_3(C=35e-6);
