  connect(voltageSource1.plug_n, star1_1.plug_p);
  connect(star1_1.pin_n, ground1.pin);
  connect(voltageSource2.plug_n, star2_1.plug_p) ;
  connect(star2_1.pin_n, ground2.pin);
  connect(voltageSource1.plug_p, currentSensor1.plug_p);
  connect(voltageSource2.plug_p, currentSensor2.plug_p) ;
  connect(resistor1_2.pin_n, inductor1_2.pin_p);
  connect(resistor1_3.pin_p, capacitor1_3.pin_p);
  connect(resistor1_3.pin_n, capacitor1_3.pin_n);
  connect(resistor2_2.pin_n, inductor2_2.pin_p);
  connect(resistor2_3.pin_n, capacitor2_3.pin_n);
  connect(resistor2_3.pin_p, capacitor2_3.pin_p) ;
  connect(currentSensor1.plug_n, plugToPins_p_1.plug_p);
  connect(currentSensor2.plug_n, plugToPins_p_2.plug_p) ;
  connect(plugToPins_p_1.pin_p[1], resistor1_1.pin_p) ;
  connect(plugToPins_p_1.pin_p[2], resistor1_2.pin_p) ;
  connect(plugToPins_p_1.pin_p[3], resistor1_3.pin_p) ;
  connect(plugToPins_p_2.pin_p[1], resistor2_1.pin_p) ;
  connect(plugToPins_p_2.pin_p[2], resistor2_2.pin_p) ;
  connect(plugToPins_p_2.pin_p[3], resistor2_3.pin_p) ;
  connect(plugToPins_n_1.pin_n[1], resistor1_1.pin_n) ;
  connect(plugToPins_n_1.pin_n[2], inductor1_2.pin_n) ;
  connect(plugToPins_n_1.pin_n[3], resistor1_3.pin_n) ;
  connect(plugToPins_n_2.pin_n[1], resistor2_1.pin_n) ;
  connect(plugToPins_n_2.pin_n[2], inductor2_2.pin_n) ;
  connect(plugToPins_n_2.pin_n[3], resistor2_3.pin_n) ;
