      Modelica.Blocks.Sources.BooleanExpression BooleanExpression1(y=time >= 2500);
      inner Modelica.StateGraph.StateGraphRoot stateGraphRoot;
      StateGraph.Step Step13(nIn=1, nOut=1);
      StateGraph.Transition Transition13b(
        condition=true,
        enableTimer=true,
        waitTime=1);
