          redeclare 
        Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPort if use_HeatTransfer;

        // Conservation of kinetic energy
        Medium.Density[nPorts] portInDensities
        "Densities of the fluid at the device boundary";
