  parameter SI.Length t(displayUnit="mm") = 0.5e-3
    "Thickness of lamination" ;

  parameter SI.Length L_l1=10e-3 "Length of leakage of primary Winding" ;
  parameter SI.Area A_l1=10e-6
    "Cross section of leakage of primary Winding" ;
  parameter Real mu_rel1=1
    "Constant relative permeability of primary leakage (>0 required)" ;
  parameter SI.Length L_l2=10e-3
    "Cross section of leakage of secondary Winding" ;
  parameter SI.Area A_l2=10e-6 "Length of leakage of secondary Winding" ;
  parameter Real mu_rel2=1
    "Constant relative permeability of secondary leakage (>0 required)" ;

  Shapes.HysteresisAndMagnets.GenericHystTellinenEverett core1(
    mat=mat,
    A=a*b,
    sigma=sigma,
    d=t,
    useHeatPort=false,
    includeEddyCurrents=EddyCurrents,
    l=l1 + 2*l2,
    H(start=HStart[1], fixed=HFixed[1]),
    MagRel(start=MagRelStart[1], fixed=MagRelFixed[1])) ;
  Shapes.HysteresisAndMagnets.GenericHystTellinenEverett core2(
    mat=mat,
    A=a*b,
    sigma=sigma,
    d=t,
    useHeatPort=false,
    includeEddyCurrents=EddyCurrents,
    l=l2,
    H(start=HStart[2], fixed=HFixed[2]),
    MagRel(start=MagRelStart[2], fixed=MagRelFixed[2])) ;

  Shapes.HysteresisAndMagnets.GenericHystTellinenEverett core3(
    mat=mat,
    A=a*b,
    includeEddyCurrents=EddyCurrents,
    sigma=sigma,
    d=t,
    l=l1 + 2*l2,
    H(start=HStart[3], fixed=HFixed[3]),
    MagRel(start=MagRelStart[3], fixed=MagRelFixed[3]));

  Basic.Ground ground;

  Basic.ElectroMagneticConverterWithLeakageInductance winding11(
    N=N1,
    L=L_l1,
    A=A_l1,
    mu_rel=mu_rel1,
    i(start=I1Start[1], fixed=I1Fixed[1])) ;

  Basic.ElectroMagneticConverterWithLeakageInductance winding12(
    L=L_l1,
    A=A_l1,
    mu_rel=mu_rel1,
    i(start=I1Start[2], fixed=I1Fixed[2]),
    final N=N1) ;

  Basic.ElectroMagneticConverterWithLeakageInductance winding13(
    N=N1,
    L=L_l1,
    A=A_l1,
    mu_rel=mu_rel1,
    i(start=I1Start[3], fixed=I1Fixed[3])) ;

   Basic.ElectroMagneticConverterWithLeakageInductance winding21(
    N=N2,
    L=L_l2,
    A=A_l2,
    mu_rel=mu_rel2,
    i(start=I2Start[1], fixed=I2Fixed[1])) ;

   Basic.ElectroMagneticConverterWithLeakageInductance winding22(
    N=N2,
    L=L_l2,
    A=A_l2,
    mu_rel=mu_rel2,
    i(start=I2Start[1], fixed=I2Fixed[1])) ;

  Basic.ElectroMagneticConverterWithLeakageInductance winding23(
    N=N2,
    L=L_l2,
    A=A_l2,
    mu_rel=mu_rel2,
    i(start=I2Start[1], fixed=I2Fixed[1])) ;

  Modelica.Electrical.Analog.Basic.Resistor resistor11(
    R=rho1*N1*L1/(pi/4*d1^2),
    useHeatPort=true,
    alpha=alpha1,
    T_ref=293.15) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor21(
    R=rho2*N2*L2/(pi/4*d2^2),
    useHeatPort=true,
    alpha=alpha2,
    T_ref=293.15) ;

  Modelica.Electrical.Analog.Basic.Resistor resistor12(
    R=rho1*N1*L1/(pi/4*d1^2),
    useHeatPort=true,
    alpha=alpha1,
    T_ref=293.15) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor22(
    R=rho2*N2*L2/(pi/4*d2^2),
    useHeatPort=true,
    alpha=alpha2,
    T_ref=293.15) ;

  Modelica.Electrical.Analog.Basic.Resistor resistor23(
    R=rho2*N2*L2/(pi/4*d2^2),
    useHeatPort=true,
    alpha=alpha2,
    T_ref=293.15) ;

  Modelica.Electrical.Analog.Basic.Resistor resistor13(
    R=rho1*N1*L1/(pi/4*d1^2),
    useHeatPort=true,
    alpha=alpha1,
    T_ref=293.15) ;
  Shapes.FixedShape.Cuboid leakage(
    nonLinearPermeability=false,
    mu_rConst=1,
    l=l2,
    a=a,
    b=b/1000);

  Modelica.Electrical.Analog.Interfaces.PositivePin p1 "Primary winding 1" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin p2 "Primary winding 2" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin p3 "Primary winding 3" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin n1 "Secondary winding 1";
  Modelica.Electrical.Analog.Interfaces.NegativePin n2 "Secondary winding 2";
  Modelica.Electrical.Analog.Interfaces.NegativePin n3 "Secondary winding 3";
  Modelica.Electrical.Analog.Interfaces.NegativePin starPoint2 "Star point of secondary windings" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin starPoint1 "Star point of primary windings" ;

equation
  v1[1] =resistor11.p.v - winding11.n.v;
  v1[2] =resistor12.p.v - winding12.n.v;
  v1[3] =resistor13.p.v - winding13.n.v;
  i1[1] =resistor11.i;
  i1[2] =resistor12.i;
  i1[3] =resistor13.i;
  R1[1] =resistor11.R_actual;
  R1[2] =resistor12.R_actual;
  R1[3] =resistor13.R_actual;

  v2[1] =resistor21.n.v - winding21.n.v;
  v2[2] =resistor21.n.v - winding21.n.v;
  v2[3] =resistor21.n.v - winding21.n.v;
  i2[1] =resistor21.i;
  i2[2] =resistor22.i;
  i2[3] =resistor23.i;
  R2[1] =resistor21.R_actual;
  R2[2] =resistor22.R_actual;
  R2[3] =resistor23.R_actual;

  B[1] =core1.B;
  B[2] =core2.B;
  B[3] =core3.B;

  Phi[1] =core1.Phi;
  Phi[2] =core2.Phi;
  Phi[3] =core3.Phi;

  Hstat[1] =core1.Hstat;
  Hstat[2] =core2.Hstat;
  Hstat[3] =core3.Hstat;
  Heddy[1] =core1.Heddy;
  Heddy[2] =core2.Heddy;
  Heddy[3] =core3.Heddy;
  H[1] =core1.H;
  H[2] =core2.H;
  H[3] =core3.H;

  Temp.T = if useHeatPort then T_heatPort else T;

  LossPowerWinding =resistor11.LossPower + resistor12.LossPower + resistor13.LossPower + resistor21.LossPower + resistor22.LossPower + resistor23.LossPower;
  LossPowerStat =core1.LossPowerStat  +core2.LossPowerStat  +core3.LossPowerStat;
  LossPowerEddy =core1.LossPowerEddy  +core2.LossPowerEddy  +core3.LossPowerEddy;
  LossPower = LossPowerWinding + LossPowerEddy + LossPowerStat;

  connect(winding11.port_n, winding21.port_p) ;
  connect(winding11.p, resistor11.n) ;
  connect(resistor11.p, p1) ;
  connect(winding12.p, resistor12.n) ;
  connect(winding13.p, resistor13.n) ;
  connect(winding12.port_p, core2.port_n) ;
  connect(winding12.port_n, winding22.port_p) ;
  connect(winding21.port_n, ground.port) ;
  connect(ground.port, winding22.port_n) ;
  connect(winding23.port_n, ground.port) ;
  connect(winding23.port_p, winding13.port_n) ;
  connect(winding13.port_p, core3.port_n) ;
  connect(p2, resistor12.p) ;
  connect(p3, resistor13.p) ;
  connect(Temp.port, resistor11.heatPort) ;
  connect(resistor12.heatPort, Temp.port) ;
  connect(resistor13.heatPort, Temp.port) ;
  connect(resistor23.heatPort, Temp.port) ;
  connect(resistor22.heatPort, Temp.port) ;
  connect(resistor21.heatPort, Temp.port) ;
  connect(resistor21.p, winding21.p) ;
  connect(resistor22.p, winding22.p) ;
  connect(resistor23.p, winding23.p) ;
  connect(resistor21.n, n1) ;
  connect(resistor22.n, n2) ;
  connect(resistor23.n, n3) ;
  connect(leakage.port_n, ground.port) ;
  connect(winding11.port_p, core1.port_n) ;
  connect(core1.port_p,core2. port_p) ;
  connect(core3.port_p,core1. port_p) ;
  connect(leakage.port_p,core3. port_p) ;

  connect(winding11.n, starPoint1) ;
  connect(starPoint1, winding13.n) ;
  connect(starPoint1, winding12.n) ;
  connect(winding21.n, starPoint2) ;
  connect(starPoint2, winding22.n) ;
  connect(winding23.n, starPoint2) ;
end Transformer3PhaseYyWithHysteresis;

