  Modelica.Electrical.Analog.Basic.Resistor resistor2(R=resistor1.R) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor3(R=resistor1.R) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode1(Vknee=0.7) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode2(Vknee=0.7) ;
  Modelica.Electrical.Analog.Basic.Resistor resistorL(R=5) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode3(Vknee=0.7) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode4(Vknee=0.7) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode5(Vknee=0.7) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode6(Vknee=0.7) ;
  Modelica.Electrical.Analog.Basic.Capacitor capacitor1(C=1e-6, v(fixed=
          true)) ;
  Modelica.Electrical.Analog.Basic.Inductor inductor1(L=1e-3) ;
  Modelica.Electrical.Analog.Basic.Inductor inductor2(L=1e-3);
  Modelica.Electrical.Analog.Basic.Inductor inductor3(L=1e-3);
  Modelica.Electrical.Analog.Basic.Capacitor capacitor2(C=1e-6, v(fixed=
          true)) ;
