  Modelica.Blocks.Sources.RealExpression rExp2(y=transformer.LossPowerEddy) ;
  Modelica.Blocks.Sources.RealExpression rExp3(y=transformer.LossPowerWinding) ;
  Modelica.Blocks.Continuous.Filter pdissStatAvg(f_cut=10)
    "Approx. average static hysteresis losses";
  Modelica.Blocks.Continuous.Filter pdissEddyAvg(f_cut=10)
    "Approx. average eddy current losses";
  Modelica.Blocks.Continuous.Filter pdissCopAvg(f_cut=10)
    "Approx. average copper losses";
initial equation
  transformer.core1.derHstat = 0.0;
  transformer.core2.derHstat = 0.0;
  transformer.core3.derHstat = 0.0;
equation
  connect(vSource1.n, ground1.p) ;
  connect(vSource2.n, ground1.p) ;
  connect(vSource3.n, ground1.p) ;
  connect(resistor1.n, transformer.p1) ;
  connect(resistor1.p, vSource1.p) ;
  connect(resistor2.n, transformer.p2) ;
  connect(resistor2.p, vSource2.p) ;
  connect(vSource3.p, resistor3.p) ;
  connect(resistor3.n, transformer.p3) ;
  connect(diode2.n, diode1.p) ;
  connect(diode4.n, diode3.p) ;
  connect(diode6.n, diode5.p) ;
  connect(diode2.p, diode4.p) ;
  connect(diode4.p, diode6.p) ;
  connect(diode1.n, diode3.n) ;
  connect(diode3.n, diode5.n) ;
  connect(diode5.n, capacitor1.p) ;
  connect(resistorL.p, capacitor1.p) ;
  connect(transformer.n1, inductor1.p) ;
  connect(transformer.n2, inductor2.p) ;
  connect(inductor2.n, diode3.p) ;
  connect(inductor3.p, transformer.n3) ;
  connect(inductor3.n, diode6.n) ;
  connect(capacitor2.n, diode6.p) ;
  connect(capacitor2.p, capacitor1.n) ;
  connect(inductor1.n, diode1.p) ;
  connect(resistorL.n, capacitor2.n) ;
  connect(transformer.starPoint1, ground1.p) ;
  connect(transformer.starPoint2, ground2.p) ;
  connect(ground2.p, capacitor2.p) ;
  connect(rExp3.y,pdissCopAvg. u) ;
  connect(rExp2.y,pdissEddyAvg. u) ;
  connect(rExp1.y,pdissStatAvg. u) ;
end ThreePhaseTransformerWithRectifier;

