model RotorSaliencyAirGap "Air gap model with rotor saliency"
  import Modelica.Constants.pi;
  Interfaces.PositiveMagneticPort port_sp
    "Positive complex magnetic stator port" ;
  Interfaces.NegativeMagneticPort port_sn
    "Negative complex magnetic stator port" ;
  Interfaces.PositiveMagneticPort port_rp
    "Positive complex magnetic rotor port" ;
  Interfaces.NegativeMagneticPort port_rn
    "Negative complex magnetic rotor port" ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a flange_a
    "Flange of the rotor" ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a support
    "Support at which the reaction torque is acting" ;
  parameter Integer p "Number of pole pairs";
  parameter Magnetic.FundamentalWave.Types.SalientInductance L0(d(start=1), q(
        start=1))
    "Salient inductance of a single unchorded coil w.r.t. the fundamental wave";
  final parameter Magnetic.FundamentalWave.Types.SalientReluctance R_m(d=1/L0.d,
      q=1/L0.q) "Reluctance of the air gap model";
  // Complex phasors of magnetic potential differences
  SI.ComplexMagneticPotentialDifference V_mss
    "Complex magnetic potential difference of stator w.r.t. stator fixed frame";
  SI.ComplexMagneticPotentialDifference V_msr
    "Complex magnetic potential difference of stator w.r.t. rotor fixed frame";
  SI.ComplexMagneticPotentialDifference V_mrr
    "Complex magnetic potential difference of rotor w.r.t. rotor fixed frame";
  // Complex phasors of magnetic fluxes
  SI.ComplexMagneticFlux Phi_ss
    "Complex magnetic flux of stator w.r.t. stator fixed frame";
  SI.ComplexMagneticFlux Phi_sr
    "Complex magnetic flux of stator w.r.t. rotor fixed frame";
  SI.ComplexMagneticFlux Phi_rr
    "Complex magnetic flux of rotor w.r.t. rotor fixed frame";
  // Electrical torque and mechanical angle
  SI.Torque tauElectrical "Electrical torque";
  SI.Angle gamma
    "Electrical angle between rotor and stator";
  Complex rotator "Equivalent vector representation of orientation";
equation
  port_sp.Phi = Phi_ss "Stator flux into positive stator port";
  port_sp.Phi + port_sn.Phi = Complex(0, 0) "Balance of stator flux";
  port_rp.Phi = Phi_rr "Rotor flux into positive rotor port";
  port_rp.Phi + port_rn.Phi = Complex(0, 0) "Balance of rotor flux";
  port_sp.V_m - port_sn.V_m = V_mss "Magnetomotive force of stator";
  port_rp.V_m - port_rn.V_m = V_mrr "Magnetomotive force of rotor";
  // Transformations between stator and rotor fixed frame
  V_msr = V_mss*Modelica.ComplexMath.conj(rotator);
  Phi_sr = Phi_ss*Modelica.ComplexMath.conj(rotator);
  // Stator flux and rotor flux are equal
  Phi_sr = Phi_rr;
  // Local balance of magnetomotive force
  (pi/2.0)*(V_mrr.re + V_msr.re) = Phi_rr.re*R_m.d;
  (pi/2.0)*(V_mrr.im + V_msr.im) = Phi_rr.im*R_m.q;
  // Torque
  tauElectrical = -(pi*p/2.0)*(Phi_ss.im*V_mss.re - Phi_ss.re*V_mss.im);
  flange_a.tau = -tauElectrical;
  support.tau = tauElectrical;
  // Electrical angle between stator and rotor
  gamma = p*(flange_a.phi - support.phi);
  rotator = Modelica.ComplexMath.exp(Complex(0, gamma));
end RotorSaliencyAirGap;

model SaliencyCageWinding "Rotor cage with saliency in d- and q-axis"
  extends Magnetic.FundamentalWave.Interfaces.TwoPortExtended;
  parameter Boolean useHeatPort=false
    "Enable / disable (=fixed temperatures) thermal port";
  parameter Magnetic.FundamentalWave.Types.SalientResistance RRef(d(start=1), q(
        start=1)) "Salient cage resistance";
  parameter SI.Temperature TRef(start=293.15)
    "Reference temperature of winding";
  parameter
    Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20
    alpha20(start=0) "Temperature coefficient of winding at 20 degC";
  final parameter SI.LinearTemperatureCoefficient alphaRef=
      Modelica.Electrical.Machines.Thermal.convertAlpha(
            alpha20,
            TRef,
            293.15) "Temperature coefficient of winding at reference temperature";
  parameter SI.Temperature TOperational(start=293.15)
    "Operational temperature of winding";
  parameter Magnetic.FundamentalWave.Types.SalientInductance Lsigma(d(start=1),
      q(start=1)) "Salient cage stray inductance";
  parameter Real effectiveTurns=1 "Effective number of turns";
  Modelica.Blocks.Interfaces.RealOutput i[2](
    each final quantity="ElectricCurrent",
    each final unit="A") = electroMagneticConverter.i
    "Currents out from damper";
  Modelica.Blocks.Interfaces.RealOutput iRMS(
    final quantity="ElectricCurrent",
    final unit="A") = sqrt(i[1]^2+i[2]^2)/sqrt(2)
    "RMS current out from damper";
  Modelica.Blocks.Interfaces.RealOutput lossPower(
    final quantity="Power",
    final unit="W") = sum(resistor.resistor.LossPower) "Damper losses";
  Magnetic.FundamentalWave.Components.PolyphaseElectroMagneticConverter electroMagneticConverter(
    final m=2,
    final orientation={0,Modelica.Constants.pi/2},
    final effectiveTurns=fill(effectiveTurns, 2)) ;
  Modelica.Electrical.Polyphase.Basic.Resistor resistor(
    final useHeatPort=useHeatPort,
    final m=2,
    final R={RRef.d,RRef.q},
    final T_ref=fill(TRef, 2),
    final alpha=fill(alphaRef, 2),
    final T=fill(TOperational, 2)) ;
  Modelica.Electrical.Polyphase.Basic.Star star(final m=2) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPortWinding if
    useHeatPort "Heat ports of winding resistor";
  Modelica.Thermal.HeatTransfer.Components.ThermalCollector thermalCollector(final m=2)
    if useHeatPort "Connector of thermal rotor resistance heat ports";
  Magnetic.FundamentalWave.Components.Reluctance strayReluctance(final R_m(d=
          effectiveTurns^2/Lsigma.d, q=effectiveTurns^2/Lsigma.q))
    "Stray reluctance equivalent to ideally coupled stray inductances";
equation
  connect(port_p, electroMagneticConverter.port_p);
  connect(electroMagneticConverter.port_n, port_n);
  connect(ground.p, star.pin_n);
  connect(electroMagneticConverter.plug_n, resistor.plug_n) ;
  connect(star.plug_p, electroMagneticConverter.plug_n) ;
  connect(thermalCollector.port_b, heatPortWinding) ;
  connect(resistor.heatPort, thermalCollector.port_a) ;
  connect(electroMagneticConverter.plug_p, resistor.plug_p) ;
  connect(strayReluctance.port_p, port_p) ;
  connect(strayReluctance.port_n, port_n) ;
end SaliencyCageWinding;

model SinglePhaseWinding
  "Symmetric winding model coupling electrical and magnetic domain"

  Modelica.Electrical.Analog.Interfaces.PositivePin pin_p "Positive pin";
  Modelica.Electrical.Analog.Interfaces.NegativePin pin_n "Negative pin";
  Magnetic.FundamentalWave.Interfaces.NegativeMagneticPort port_n
    "Negative complex magnetic port";
  Magnetic.FundamentalWave.Interfaces.PositiveMagneticPort port_p
    "Positive complex magnetic port";
  parameter Boolean useHeatPort=false
    "Enable / disable (=fixed temperatures) thermal port";
  parameter SI.Resistance RRef
    "Winding resistance per phase at TRef";
  parameter SI.Temperature TRef(start=293.15)
    "Reference temperature of winding";
  parameter
    Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20
    alpha20(start=0) "Temperature coefficient of winding at 20 degC";
  final parameter SI.LinearTemperatureCoefficient alphaRef=
      Modelica.Electrical.Machines.Thermal.convertAlpha(
            alpha20,
            TRef,
            293.15) "Temperature coefficient of winding at reference temperature";
  parameter SI.Temperature TOperational(start=293.15)
    "Operational temperature of winding";
  parameter SI.Inductance Lsigma
    "Winding stray inductance per phase";
  parameter Real effectiveTurns=1 "Effective number of turns per phase";
  parameter SI.Angle orientation
    "Orientation of the resulting fundamental wave field phasor";

  SI.Voltage v=pin_p.v - pin_n.v "Voltage";
  SI.Current i=pin_p.i "Current";

  SI.ComplexMagneticPotentialDifference V_m=port_p.V_m -
      port_n.V_m "Complex magnetic potential difference";
  SI.MagneticPotentialDifference abs_V_m=
      Modelica.ComplexMath.abs(V_m)
    "Magnitude of complex magnetic potential difference";
  SI.Angle arg_V_m=Modelica.ComplexMath.arg(V_m)
    "Argument of complex magnetic potential difference";
  SI.ComplexMagneticFlux Phi=port_p.Phi
    "Complex magnetic flux";
  SI.MagneticFlux abs_Phi=
      Modelica.ComplexMath.abs(Phi)
    "Magnitude of complex magnetic flux";
  SI.Angle arg_Phi=Modelica.ComplexMath.arg(Phi)
    "Argument of complex magnetic flux";

  Modelica.Electrical.Analog.Basic.Resistor resistor(
    final useHeatPort=useHeatPort,
    final R=RRef,
    final T_ref=TRef,
    final alpha=alphaRef,
    final T=TOperational) ;
  Magnetic.FundamentalWave.Components.SinglePhaseElectroMagneticConverter electroMagneticConverter(final
      effectiveTurns=effectiveTurns, final orientation=orientation) "Winding";
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPortWinding if
    useHeatPort "Heat ports of winding resistor";
  Modelica.Magnetic.FundamentalWave.Components.Permeance stray(final G_m(d=
          Lsigma/effectiveTurns^2, q=Lsigma/effectiveTurns^2)) ;
equation
  connect(pin_p, resistor.p) ;
  connect(electroMagneticConverter.pin_n, pin_n) ;
  connect(electroMagneticConverter.port_p, port_p) ;
  connect(electroMagneticConverter.port_n, port_n) ;
  connect(heatPortWinding, resistor.heatPort) ;
  connect(resistor.n, electroMagneticConverter.pin_p) ;
  connect(electroMagneticConverter.port_p, stray.port_p);
  connect(electroMagneticConverter.port_n, stray.port_n);
end SinglePhaseWinding;

model SymmetricPolyphaseCageWinding "Symmetrical rotor cage"
  import Modelica.Constants.pi;
  extends Magnetic.FundamentalWave.Interfaces.TwoPortExtended;
  parameter Integer m=3 "Number of phases" ;
  parameter Boolean useHeatPort=false
    "Enable / disable (=fixed temperatures) thermal port";
  parameter SI.Resistance RRef
    "Winding resistance per phase at TRef";
  parameter SI.Temperature TRef(start=293.15)
    "Reference temperature of winding";
  parameter
    Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20
    alpha20(start=0) "Temperature coefficient of winding at 20 degC";
  final parameter SI.LinearTemperatureCoefficient alphaRef=
      Modelica.Electrical.Machines.Thermal.convertAlpha(
            alpha20,
            TRef,
            293.15) "Temperature coefficient of winding at reference temperature";
  parameter SI.Temperature TOperational(start=293.15)
    "Operational temperature of winding";
  parameter SI.Inductance Lsigma "Cage stray inductance";
  parameter Real effectiveTurns=1 "Effective number of turns";
  final parameter Integer nBase=Modelica.Electrical.Polyphase.Functions.numberOfSymmetricBaseSystems(m)
    "Number of base systems";
  SI.Current i[m]=electroMagneticConverter.i
    "Cage currents";
  Magnetic.FundamentalWave.Components.PolyphaseElectroMagneticConverter electroMagneticConverter(
    final m=m,
    final effectiveTurns=fill(effectiveTurns, m),
    final orientation=
        Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m))
    "Symmetric winding" ;
  Modelica.Electrical.Polyphase.Basic.Resistor resistor(
    final useHeatPort=useHeatPort,
    final m=m,
    final R=fill(RRef, m),
    final T_ref=fill(TRef, m),
    final alpha=fill(alphaRef, m),
    final T=fill(TOperational, m)) ;
  Modelica.Electrical.Polyphase.Basic.Star star(final m=nBase);
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPortWinding if
    useHeatPort "Heat ports of winding resistor";
  Modelica.Thermal.HeatTransfer.Components.ThermalCollector thermalCollector(final m=m)
    if useHeatPort "Connector of thermal rotor resistance heat ports";
  Magnetic.FundamentalWave.Components.Reluctance strayReluctance(final R_m(d=m*
          effectiveTurns^2/2/Lsigma, q=m*effectiveTurns^2/2/Lsigma))
    "Stray reluctance equivalent to ideally coupled stray inductances";
  Modelica.Electrical.Polyphase.Basic.MultiStar multiStar(final m=m);
equation
  connect(port_p, electroMagneticConverter.port_p);
  connect(electroMagneticConverter.port_n, port_n) ;
  connect(ground.p, star.pin_n) ;
  connect(thermalCollector.port_a, resistor.heatPort) ;
  connect(thermalCollector.port_b, heatPortWinding) ;
  connect(strayReluctance.port_p, port_p) ;
  connect(strayReluctance.port_n, port_n) ;
  connect(electroMagneticConverter.plug_p, resistor.plug_p) ;
  connect(electroMagneticConverter.plug_n, multiStar.plug_p);
  connect(multiStar.starpoints, star.plug_p);
  connect(resistor.plug_n, multiStar.plug_p);
end SymmetricPolyphaseCageWinding;

model SymmetricPolyphaseWinding
  "Symmetric winding model coupling electrical and magnetic domain"
  // Orientation changed
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_p(final m=m)
    "Positive plug" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_n(final m=m)
    "Negative plug" ;
  Magnetic.FundamentalWave.Interfaces.NegativeMagneticPort port_n
    "Negative complex magnetic port";
  Magnetic.FundamentalWave.Interfaces.PositiveMagneticPort port_p
    "Positive complex magnetic port";
  parameter Integer m=3 "Number of phases" ;
  parameter Boolean useHeatPort=false
    "Enable / disable (=fixed temperatures) thermal port";
  // Resistor model
  parameter SI.Resistance RRef
    "Winding resistance per phase at TRef";
  parameter SI.Temperature TRef(start=293.15)
    "Reference temperature of winding";
  parameter
    Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20
    alpha20(start=0) "Temperature coefficient of winding at 20 degC";
  final parameter SI.LinearTemperatureCoefficient alphaRef=
      Modelica.Electrical.Machines.Thermal.convertAlpha(
            alpha20,
            TRef,
            293.15) "Temperature coefficient of winding at reference temperature";
  parameter SI.Temperature TOperational(start=293.15)
    "Operational temperature of winding";
  parameter SI.Inductance Lsigma
    "Winding stray inductance per phase";
  parameter SI.Inductance Lzero
    "Zero sequence inductance of winding";
  parameter Real effectiveTurns=1 "Effective number of turns per phase";
  parameter SI.Conductance GcRef
    "Electrical reference core loss reluctance";
  final parameter Integer nBase=Modelica.Electrical.Polyphase.Functions.numberOfSymmetricBaseSystems(m)
    "Number of base systems";
  final parameter Integer mBase=integer(m/nBase)
    "Number of phase of the base systems";

  SI.Voltage v[m]=plug_p.pin.v - plug_n.pin.v "Voltage";
  SI.Current i[m]=plug_p.pin.i "Current";

  SI.ComplexMagneticPotentialDifference V_m=port_p.V_m -
      port_n.V_m "Complex magnetic potential difference";
  SI.MagneticPotentialDifference abs_V_m=
      Modelica.ComplexMath.abs(V_m)
    "Magnitude of complex magnetic potential difference";
  SI.Angle arg_V_m=Modelica.ComplexMath.arg(V_m)
    "Argument of complex magnetic potential difference";
  SI.ComplexMagneticFlux Phi=port_p.Phi
    "Complex magnetic flux";
  SI.MagneticFlux abs_Phi=
      Modelica.ComplexMath.abs(Phi)
    "Magnitude of complex magnetic flux";
  SI.Angle arg_Phi=Modelica.ComplexMath.arg(Phi)
    "Argument of complex magnetic flux";

  Magnetic.FundamentalWave.Components.PolyphaseElectroMagneticConverter electroMagneticConverter(
    final m=m,
    final effectiveTurns=fill(effectiveTurns, m),
    final orientation=
        Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m))
    "Symmetric winding";
  Modelica.Electrical.Polyphase.Basic.ZeroInductor zeroInductor(final m=m, final Lzero=Lzero) if
       mBase<>2 "Zero sequence inductance of winding";
  Modelica.Electrical.Polyphase.Ideal.Short short(final m=m) if mBase == 2;
  Modelica.Electrical.Polyphase.Basic.Resistor resistor(
    final m=m,
    final useHeatPort=useHeatPort,
    final R=fill(RRef, m),
    final T_ref=fill(TRef, m),
    final alpha=fill(alphaRef, m),
    final T=fill(TOperational, m)) "Winding resistor" ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPortWinding[m] if
    useHeatPort "Heat ports of winding resistors";
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPortCore if
    useHeatPort "Heat port of core";
  Magnetic.FundamentalWave.Components.EddyCurrent core(final useHeatPort=
        useHeatPort, final G=(m/2)*GcRef*effectiveTurns^2)
    "Core loss model (currently eddy currents only)" ;
  Modelica.Magnetic.FundamentalWave.Components.Permeance stray(
    final G_m(d=2*Lsigma/m/effectiveTurns^2, q=2*Lsigma/m/effectiveTurns^2))
    "Stray permeance equivalent to ideally coupled stray inductances" ;

equation
  connect(plug_p, resistor.plug_p) ;
  connect(resistor.plug_n, zeroInductor.plug_p) ;
  connect(electroMagneticConverter.plug_n, plug_n) ;
  connect(electroMagneticConverter.port_p, port_p) ;
  connect(resistor.heatPort, heatPortWinding) ;
  connect(electroMagneticConverter.port_n, core.port_p) ;
  connect(core.port_n, port_n) ;
  connect(core.heatPort, heatPortCore) ;
  connect(stray.port_n, core.port_n) ;
  connect(stray.port_p, electroMagneticConverter.port_p) ;
  connect(zeroInductor.plug_n, electroMagneticConverter.plug_p) ;
  connect(resistor.plug_n, short.plug_p);
  connect(electroMagneticConverter.plug_p, short.plug_n) ;
end SymmetricPolyphaseWinding;

