      p=p) ;
  Modelica.Electrical.Machines.Sensors.RotorDisplacementAngle rotorAngleE(
      p=p) ;
  Modelica.Electrical.Machines.Sensors.MechanicalPowerSensor
    mechanicalPowerSensorM ;
  Modelica.Electrical.Machines.Sensors.MechanicalPowerSensor
    mechanicalPowerSensorE ;
  Modelica.Mechanics.Rotational.Sources.ConstantSpeed constantSpeedM(
      final w_fixed=w, useSupport=false) ;
  Modelica.Mechanics.Rotational.Sources.ConstantSpeed constantSpeedE(
      final w_fixed=w, useSupport=false) ;
  parameter Modelica.Electrical.Machines.Utilities.SynchronousMachineData smeeData(
    SNominal=30e3,
    VsNominal=100,
    fsNominal=50,
    IeOpenCircuit=10,
    x0=0.1,
    xd=1.6,
    xq=1.6,
    xdTransient=0.1375,
    xdSubtransient=0.121428571,
    xqSubtransient=0.148387097,
    Ta=0.014171268,
    Td0Transient=0.261177343,
    Td0Subtransient=0.006963029,
    Tq0Subtransient=0.123345081,
    alpha20s(displayUnit="1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero,

    alpha20r(displayUnit="1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero,

    alpha20e(displayUnit="1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero,

    TsSpecification=293.15,
    TsRef=293.15,
    TrSpecification=293.15,
    TrRef=293.15,
    TeSpecification=293.15,
    TeRef=293.15) "Synchronous machine data";
  SI.Angle thetaM=rotorAngleM.rotorDisplacementAngle "Rotor displacement angle, FundamentalWave machine";
  SI.Angle thetaE=rotorAngleE.rotorDisplacementAngle "Rotor displacement angle, Electrical machine";

initial equation
  smeeE.is[1:2] = zeros(2);
  smeeM.is[1:2] = zeros(2);
  //conditional damper cage currents are defined as fixed start values
equation
  connect(rotorAngleE.plug_n, smeeE.plug_sn) ;
  connect(rotorAngleE.plug_p, smeeE.plug_sp);
  connect(rotorAngleE.flange, smeeE.flange);
  connect(star.pin_n, ground.p);
  connect(star.plug_p, sineVoltage.plug_n);
  connect(smeeE.flange, mechanicalPowerSensorE.flange_a);
  connect(mechanicalPowerSensorE.flange_b, constantSpeedE.flange);
  connect(rampCurrentE.p, groundE.p);
  connect(rampCurrentE.p, smeeE.pin_en) ;
  connect(rampCurrentE.n, smeeE.pin_ep) ;
  connect(smeeE.plug_sn, terminalBoxE.plug_sn);
  connect(smeeE.plug_sp, terminalBoxE.plug_sp);
  connect(rotorAngleM.plug_n, smeeM.plug_sn) ;
  connect(rotorAngleM.plug_p, smeeM.plug_sp) ;
  connect(rotorAngleM.flange, smeeM.flange) ;
  connect(smeeM.flange, mechanicalPowerSensorM.flange_a);
  connect(mechanicalPowerSensorM.flange_b, constantSpeedM.flange);
  connect(rampCurrentM.p, groundM.p) ;
  connect(rampCurrentM.p, smeeM.pin_en) ;
  connect(rampCurrentM.n, smeeM.pin_ep) ;
  connect(smeeM.plug_sn, terminalBoxM.plug_sn);
  connect(smeeM.plug_sp, terminalBoxM.plug_sp);
  connect(electricalPowerSensorM.plug_p, sineVoltage.plug_p) ;
  connect(electricalPowerSensorE.plug_p, sineVoltage.plug_p) ;
  connect(electricalPowerSensorM.plug_ni, terminalBoxM.plugSupply);
  connect(electricalPowerSensorE.plug_ni, terminalBoxE.plugSupply);
  connect(electricalPowerSensorE.plug_nv, star.plug_p) ;
  connect(electricalPowerSensorM.plug_nv, star.plug_p) ;
end SMEE_Generator;

model SMEE_LoadDump
  "Test example: ElectricalExcitedSynchronousMachine with voltage controller"

  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  constant Integer m=3 "Number of phases";
  parameter SI.AngularVelocity wNominal=2*pi*smeeData.fsNominal
      /smee.p "Nominal speed";
  parameter SI.Impedance ZNominal=3*smeeData.VsNominal^2/
      smeeData.SNominal "Nominal load impedance";
  parameter Real powerFactor(
    min=0,
    max=1) = 0.8 "Load power factor";
  parameter SI.Resistance RLoad=ZNominal*powerFactor
    "Load resistance";
  parameter SI.Inductance LLoad=ZNominal*sqrt(1 -
      powerFactor^2)/(2*pi*smeeData.fsNominal) "Load inductance";
  parameter SI.Voltage Ve0=smee.IeOpenCircuit*
      Modelica.Electrical.Machines.Thermal.convertResistance(
            smee.Re,
            smee.TeRef,
            smee.alpha20e,
            smee.TeOperational) "No load excitation voltage";
  parameter Real k=2*Ve0/smeeData.VsNominal "Voltage controller: gain";
  parameter SI.Time Ti=smeeData.Td0Transient/2
    "Voltage controller: integral time constant";
  output Real controlError=(setPointGain.y - voltageQuasiRMSSensor.V)/
      smeeData.VsNominal;
  Magnetic.FundamentalWave.BasicMachines.SynchronousMachines.SM_ElectricalExcited
    smee(
    fsNominal=smeeData.fsNominal,
    TsRef=smeeData.TsRef,
    Lrsigmad=smeeData.Lrsigmad,
    Lrsigmaq=smeeData.Lrsigmaq,
    Rrd=smeeData.Rrd,
    Rrq=smeeData.Rrq,
    TrRef=smeeData.TrRef,
    VsNominal=smeeData.VsNominal,
    IeOpenCircuit=smeeData.IeOpenCircuit,
    Re=smeeData.Re,
    TeRef=smeeData.TeRef,
    sigmae=smeeData.sigmae,
    useDamperCage=true,
    p=2,
    Jr=0.29,
    Js=0.29,
    statorCoreParameters(VRef=100),
    strayLoadParameters(IRef=100),
    brushParameters(ILinear=0.01),
    Rs=smeeData.Rs*m/3,
    Lssigma=smeeData.Lssigma*m/3,
    Lmd=smeeData.Lmd*m/3,
    Lmq=smeeData.Lmq*m/3,
    TsOperational=293.15,
    alpha20s=smeeData.alpha20s,
    effectiveStatorTurns=smeeData.effectiveStatorTurns,
    alpha20r=smeeData.alpha20r,
    TrOperational=293.15,
    TeOperational=293.15,
    alpha20e=smeeData.alpha20e);
  parameter Modelica.Electrical.Machines.Utilities.SynchronousMachineData smeeData(
    SNominal=30e3,
    VsNominal=100,
    fsNominal=50,
    IeOpenCircuit=10,
    x0=0.1,
    xd=1.6,
    xq=1.6,
    xdTransient=0.1375,
    xdSubtransient=0.121428571,
    xqSubtransient=0.148387097,
    Ta=0.014171268,
    Td0Transient=0.261177343,
    Td0Subtransient=0.006963029,
    Tq0Subtransient=0.123345081,
    TsSpecification=293.15,
    TsRef=293.15,
    alpha20s(displayUnit="1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero,

    TrSpecification=293.15,
    TrRef=293.15,
    alpha20r(displayUnit="1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero,

    TeSpecification=293.15,
    TeRef=293.15,
    alpha20e(displayUnit="1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero)
    "Synchronous machine data";

  Modelica.Electrical.Machines.Utilities.TerminalBox terminalBox(
      terminalConnection="Y");
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Mechanics.Rotational.Sources.Speed speed;
  Modelica.Blocks.Sources.Ramp speedRamp(height=wNominal, duration=1);
  Modelica.Mechanics.Rotational.Sensors.SpeedSensor speedSensor;
  Modelica.Blocks.Math.Gain setPointGain(k=(smeeData.VsNominal/wNominal)/
        unitMagneticFlux);
  Modelica.Electrical.Machines.Sensors.VoltageQuasiRMSSensor voltageQuasiRMSSensor(
      ToSpacePhasor1(y(each start=1E-3, each fixed=true))) ;
  Modelica.Blocks.Continuous.LimPID voltageController(
    controllerType=Modelica.Blocks.Types.SimpleController.PI,
    k=k,
    Ti=Ti,
    yMax=2.5*Ve0,
    yMin=0,
    initType=Modelica.Blocks.Types.Init.InitialState,
    Td=0.001);
  Modelica.Electrical.Analog.Sources.SignalVoltage excitationVoltage;
  Modelica.Electrical.Analog.Basic.Ground groundExcitation ;
  Modelica.Electrical.Machines.Sensors.CurrentQuasiRMSSensor currentQuasiRMSSensor;
  Modelica.Blocks.Sources.BooleanPulse loadControl(period=4, startTime=2);
  Modelica.Electrical.Polyphase.Ideal.CloserWithArc switch(
    m=m,
    Ron=fill(1e-5, m),
    Goff=fill(1e-5, m),
    V0=fill(30, m),
    dVdt=fill(10e3, m),
    Vmax=fill(60, m),
    closerWithArc(off(start=fill(true, m), fixed=fill(true, m))));
  Modelica.Electrical.Polyphase.Basic.Resistor loadResistor(m=m, R=fill(
        RLoad, m));
  Modelica.Electrical.Polyphase.Basic.Inductor loadInductor(m=m, L=fill(
        LLoad, m));
  Modelica.Electrical.Polyphase.Basic.Star star(m=m) ;
protected
  constant SI.MagneticFlux unitMagneticFlux=1;
public
  Modelica.Blocks.Routing.BooleanReplicator booleanReplicator(nout=m);
initial equation
  smee.airGap.V_msr = Complex(0, 0);
  //conditional damper cage currents are defined as fixed start values
  smee.ie = 0;
equation
  connect(terminalBox.plug_sn, smee.plug_sn) ;
  connect(terminalBox.plug_sp, smee.plug_sp) ;
  connect(excitationVoltage.p, smee.pin_ep) ;
  connect(excitationVoltage.n, smee.pin_en) ;
  connect(excitationVoltage.n, groundExcitation.p) ;
  connect(voltageQuasiRMSSensor.plug_n, smee.plug_sn) ;
  connect(voltageQuasiRMSSensor.plug_p, smee.plug_sp) ;
  connect(terminalBox.plugSupply, currentQuasiRMSSensor.plug_n);
  connect(smee.flange, speed.flange) ;
  connect(speed.flange, speedSensor.flange) ;
  connect(speedRamp.y, speed.w_ref) ;
  connect(setPointGain.y, voltageController.u_s) ;
  connect(speedSensor.w, setPointGain.u) ;
  connect(voltageQuasiRMSSensor.V, voltageController.u_m) ;
  connect(voltageController.y, excitationVoltage.v) ;
  connect(loadInductor.plug_p, loadResistor.plug_n) ;
  connect(loadResistor.plug_p, switch.plug_n) ;
  connect(switch.plug_p, currentQuasiRMSSensor.plug_p) ;
  connect(star.plug_p, loadInductor.plug_n) ;
  connect(star.pin_n, ground.p) ;
  connect(loadControl.y, booleanReplicator.u) ;
  connect(booleanReplicator.y, switch.control) ;
end SMEE_LoadDump;

