      wRef=wNominal),
    Lm=66.4/(2*pi*fNominal),
    Lrsigma=2.31/(2*pi*fNominal),
    Rr=0.42,
    alpha20r(displayUnit="1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Aluminium)
    "Induction machine data";

equation
  connect(starQS.pin_n, groundQS.pin) ;
  connect(sineVoltageQS.plug_n, starQS.plug_p) ;
  connect(terminalBoxQS.plug_sn, imcQS.plug_sn) ;
  connect(terminalBoxQS.plug_sp, imcQS.plug_sp) ;

  connect(imcQS.flange, powerSensorQS.flange_a) ;
  connect(powerSensorQS.flange_b, loadInertiaQS.flange_a) ;
  connect(torqueQS.flange, loadInertiaQS.flange_b) ;
  connect(sineVoltageQS.plug_p, currentQuasiRMSSensorQS.plug_p) ;
  connect(PIQS.y, gainQS.u) ;
  connect(currentQuasiRMSSensorQS.plug_n, electricalPowerSensorQS.currentP) ;
  connect(electricalPowerSensorQS.currentN, terminalBoxQS.plugSupply) ;
  connect(electricalPowerSensorQS.currentP, electricalPowerSensorQS.voltageP) ;
  connect(electricalPowerSensorQS.voltageN, starQS.plug_p) ;
  connect(powerSensorQS.power, combiTable1DsQS.u) ;
  connect(powerSensorQS.power, feedbackQS.u2) ;
  connect(gainQS.y, torqueQS.tau) ;
  connect(rampQS.y, feedbackQS.u1) ;
  connect(feedbackQS.y, PIQS.u) ;
