model EddyCurrentLosses
  "Comparison of equivalent circuits of eddy current loss models"
  extends Modelica.Icons.Example;
  constant Integer m=3 "Number of phases";
  // ## Original value R = 0.1 Ohm
  parameter SI.Resistance R=0.1 "Resistance";
  parameter SI.Conductance Gc=0.0001 "Loss conductance";
  parameter SI.Reluctance R_m=1
    "Reluctance of the magnetic circuit";
  parameter Real N=1 "Number of turns";
  output SI.Power lossPower_e=sum(loss_e.conductor.LossPower);
  output SI.Power lossPower_m=loss_m.lossPower;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground_e;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground_m;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star star_e(m=m);
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star star_m(m=m);
  Modelica.Electrical.QuasiStatic.Polyphase.Sources.VoltageSource
    sineVoltage_e(
    m=m,
    f=1,
    phi=-Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m),
    V=fill(1/sqrt(2), m),
    gamma(fixed=true, start=0));

  Modelica.Electrical.QuasiStatic.Polyphase.Sources.VoltageSource
    sineVoltage_m(
    m=m,
    f=1,
    phi=-Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m),
    V=fill(1/sqrt(2), m),
    gamma(fixed=true, start=0));

  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Resistor
    resistor_e(m=m, R_ref=fill(R*m/3, m)) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Resistor
    resistor_m(m=m, R_ref=fill(R*m/3, m)) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor
    powerb_e(m=m);
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor
    powerb_m(m=m);
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Conductor loss_e(m=
       m,G_ref=fill(Gc*3/m, m)) ;
  Magnetic.QuasiStatic.FundamentalWave.Components.PolyphaseElectroMagneticConverter
    converter_e(effectiveTurns=N);
  Magnetic.QuasiStatic.FundamentalWave.Components.PolyphaseElectroMagneticConverter
    converter_m(effectiveTurns=N);
  Magnetic.QuasiStatic.FundamentalWave.Components.EddyCurrent loss_m(G=m*N^2*Gc
        /2) ;
  Magnetic.QuasiStatic.FundamentalWave.Components.Reluctance reluctance_e(R_m(d=R_m,
        q=R_m)) ;
  Magnetic.QuasiStatic.FundamentalWave.Components.Reluctance reluctance_m(R_m(d=R_m,
        q=R_m)) ;
  Magnetic.QuasiStatic.FundamentalWave.Components.Ground mground_e;
  Magnetic.QuasiStatic.FundamentalWave.Components.Ground mground_m;
equation
  connect(sineVoltage_e.plug_n, converter_e.plug_n) ;
  connect(sineVoltage_e.plug_n, star_e.plug_p) ;
  connect(converter_e.port_p, reluctance_e.port_p) ;
  connect(converter_e.port_n, reluctance_e.port_n) ;
  connect(converter_e.port_n, mground_e.port_p) ;
  connect(resistor_e.plug_p, sineVoltage_e.plug_p) ;
  connect(loss_e.plug_n, sineVoltage_e.plug_n) ;
  connect(loss_e.plug_p, converter_e.plug_p) ;
  connect(resistor_e.plug_n, powerb_e.currentP) ;
  connect(powerb_e.currentN, converter_e.plug_p) ;
  connect(star_e.pin_n, ground_e.pin) ;
  connect(powerb_e.currentP, powerb_e.voltageP) ;
  connect(powerb_e.voltageN, sineVoltage_e.plug_n) ;
  connect(sineVoltage_m.plug_n, star_m.plug_p) ;
  connect(sineVoltage_m.plug_n, converter_m.plug_n) ;
  connect(converter_m.port_n, reluctance_m.port_n) ;
  connect(converter_m.port_p, loss_m.port_p) ;
  connect(loss_m.port_n, reluctance_m.port_p) ;
  connect(converter_m.port_n, mground_m.port_p) ;
  connect(sineVoltage_m.plug_p, resistor_m.plug_p) ;
  connect(resistor_m.plug_n, powerb_m.currentP) ;
  connect(powerb_m.currentN, converter_m.plug_p) ;
  connect(star_m.pin_n, ground_m.pin) ;
  connect(powerb_m.currentP, powerb_m.voltageP) ;
  connect(powerb_m.voltageN, sineVoltage_m.plug_n) ;
end EddyCurrentLosses;

model PolyphaseInductance "Polyphase inductance"
  extends Modelica.Icons.Example;
  parameter Integer m=5 "Number of phases" ;
  parameter SI.Frequency f=1 "Supply frequency";
  parameter SI.Voltage VRMS=100 "RMS supply voltage";
  parameter SI.Resistance R=1E-5 "Resistance";
  parameter SI.Inductance L=1 "Load inductance";
  parameter Real effectiveTurns=5 "Effective number of turns";
  // Symmetrical polyphase magnetic reluctance
  final parameter SI.Reluctance R_m=m*effectiveTurns^2/2/L
    "Equivalent magnetic reluctance";
  output SI.ComplexCurrent Ie=resistor_e.i[1]
    "Current of electric representation";
  output SI.ComplexCurrent Im=resistor_m.i[1]
    "Current of magnetic representation";
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground_e;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground_m;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star star_e(m=m);
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star star_m(m=m);
  Modelica.Electrical.QuasiStatic.Polyphase.Sources.VoltageSource
    voltageSource_e(
    m=m,
    f=f,
    phi=-Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m),
    V=fill(VRMS, m),
    gamma(fixed=true, start=0));

  Modelica.Electrical.QuasiStatic.Polyphase.Sources.VoltageSource
    voltageSource_m(
    m=m,
    f=f,
    phi=-Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m),
    V=fill(VRMS, m),
    gamma(fixed=true, start=0));

  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Resistor
    resistor_e(m=m, R_ref=fill(R*m/3, m));
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Resistor
    resistor_m(m=m, R_ref=fill(R*m/3, m));
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Inductor
    inductor_e(m=m, L=fill(L, m)) ;
  Magnetic.QuasiStatic.FundamentalWave.Components.PolyphaseElectroMagneticConverter
    converter_m(m=m, effectiveTurns=effectiveTurns);
  Magnetic.QuasiStatic.FundamentalWave.Components.Reluctance reluctance_m(R_m(d=R_m,
        q=R_m)) ;
  Magnetic.QuasiStatic.FundamentalWave.Components.Ground groundM_m;
equation
  connect(star_e.pin_n, ground_e.pin) ;
  connect(star_e.plug_p, voltageSource_e.plug_n) ;
  connect(voltageSource_e.plug_n, inductor_e.plug_n) ;
  connect(converter_m.port_p, reluctance_m.port_p) ;
  connect(converter_m.port_n, reluctance_m.port_n) ;
  connect(converter_m.port_n, groundM_m.port_p) ;
  connect(voltageSource_m.plug_n, star_m.plug_p) ;
  connect(star_m.pin_n, ground_m.pin) ;
  connect(voltageSource_m.plug_n, converter_m.plug_n) ;
  connect(voltageSource_e.plug_p, resistor_e.plug_p) ;
  connect(resistor_e.plug_n, inductor_e.plug_p) ;
  connect(voltageSource_m.plug_p, resistor_m.plug_p) ;
  connect(resistor_m.plug_n, converter_m.plug_p) ;
end PolyphaseInductance;

