function atan2 "Four quadrant inverse tangent"
  extends Modelica.Math.Icons.AxisCenter;
  input Real u1 "First independent variable";
  input Real u2 "Second independent variable";
  output Modelica.Units.SI.Angle y "Dependent variable y=atan2(u1, u2)=atan(u1/u2)";

external "builtin" y = atan2(u1, u2);
end atan2;

function atan3
  "Four quadrant inverse tangent (select solution that is closest to given angle y0)"
  import Modelica.Constants.pi;
  extends Modelica.Math.Icons.AxisCenter;
  input Real u1 "First independent variable";
  input Real u2 "Second independent variable";
  input Modelica.Units.SI.Angle y0=0 "y shall be in the range: -pi < y-y0 <= pi";
  output Modelica.Units.SI.Angle y "Dependent variable y=atan3(u1, u2, y0)=atan(u1/u2)";

protected
  constant Real pi2=2*pi;
  Real w;
algorithm
  w := Math.atan2(u1, u2);
  if y0 == 0 then
    // For the default (y0 = 0), exactly the same result as with atan2(..) is returned
    y := w;
  else
    /* -pi < y - y0 <= pi
       -pi < w + 2*pi*N - y0 <= pi
       (-pi+y0-w)/(2*pi) < N <= (pi+y0-w)/(2*pi)
       -> N := integer( (pi+y0-w)/(2*pi) )
    */
    y := w + pi2*integer((pi+y0-w)/pi2);
  end if;
end atan3;

function allTrue
    "Returns true, if all elements of the Boolean input vector are true ('and')"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Boolean result "= true, if all elements of b are true";
algorithm
  result := size(b,1) > 0;
  for i in 1:size(b,1) loop
     result := result and b[i];
  end for;
end allTrue;

function andTrue
    "Returns true, if all elements of the Boolean input vector are true ('and')"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Boolean result "= true, if all elements of b are true";
algorithm
  result := true;
  for i in 1:size(b,1) loop
     result := result and b[i];
  end for;
end andTrue;

function anyTrue
    "Returns true, if at least one element of the Boolean input vector is true ('or')"

  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Boolean result "= true, if at least one element of b is true";
algorithm
  result := false;
  for i in 1:size(b,1) loop
     result := result or b[i];
  end for;
end anyTrue;

function countTrue "Returns the number of true elements in a Boolean vector"

  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Integer n "Number of true elements in b";
algorithm
  n := sum(if b[i] then 1 else 0 for i in 1:size(b, 1));
end countTrue;

function enumerate
    "Enumerates the true elements in a Boolean vector (0 for false elements)"
  extends Modelica.Icons.Function;

  input Boolean b[:] "Boolean vector";
  output Integer enumerated[size(b, 1)]
      "Indices of the true elements in b (increasing order; 0 for false elements)";

  protected
  Integer count;

algorithm
    count := 1;
    for i in 1:size(b, 1) loop
      if b[i] then
        enumerated[i] := count;
        count := count + 1;
      else
        enumerated[i] := 0;
      end if;
    end for;
end enumerate;

function firstTrueIndex
    "Returns the index of the first true element of a Boolean vector"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Integer index "Index of the first true element of b";
algorithm
   index :=0;
   for i in 1:size(b,1) loop
      if b[i] then
         index :=i;
         return;
      end if;
   end for;
end firstTrueIndex;

function index "Returns the indices of the true elements of a Boolean vector"
  extends Modelica.Icons.Function;

  input Boolean b[:] "Boolean vector";
  output Integer indices[countTrue(b)] "Indices of the true elements of b";

  protected
  Integer count;

algorithm
    count := 1;
    for i in 1:size(b, 1) loop
      if b[i] then
        indices[count] := i;
        count := count + 1;
      end if;
    end for;
end index;

function oneTrue
    "Returns true, if exactly one element of the Boolean input vector is true (\"xor\")"
  extends Modelica.Icons.Function;

  input Boolean b[:] "Boolean vector";
  output Boolean result "= true, if exactly one element of b is true";

algorithm
  result := countTrue(b) == 1;
end oneTrue;

