    cylinderInclinationAngle=Cv.from_deg(-30),
    animation=animation,
    crankAngleOffset=Cv.from_deg(210));
  Utilities.Cylinder cylinder4(
    cylinderInclinationAngle=Cv.from_deg(30),
    animation=animation,
    crankAngleOffset=Cv.from_deg(210));
