  extends Modelica.Icons.Function;

  input Real u1;
  input Real u2;
  input Real u1_d;
  input Real u2_d;
  output Real y_d;
algorithm
  y_d := if u1 > u2 then u1_d else u2_d;
end maxWithoutEvent_d;

function maxWithoutEvent_dd
  "First derivative of function maxWithoutEvent_d(..)"
  extends Modelica.Icons.Function;

  input Real u1;
  input Real u2;
  input Real u1_d;
  input Real u2_d;
  input Real u1_dd;
  input Real u2_dd;
