  connect(jointUSP.frame_b, frame_b);
  connect(jointUSP.frame_ia, frame_ia) ;
  connect(jointUSP.frame_im, frame_im) ;
  connect(jointUSP.frame_ib, frame_ib) ;
  connect(jointUSP.axis, axis);
  connect(jointUSP.bearing, bearing);
end JointRRP;

