function pipeWithScalarField
  "Function defining the surface characteristic of a pipe where a scalar field value is displayed with color along the pipe axis"
  extends Modelica.Mechanics.MultiBody.Interfaces.partialSurfaceCharacteristic(
    final multiColoredSurface=true);
  input SI.Radius rOuter "Outer radius of cylinder" ;
  input SI.Length length "Length of cylinder" ;
  input SI.Position xsi[:]
    "Relative position along the pipe with x[1] = 0, x[end] = 1" ;
  input Real T[size(xsi,1)] "Scalar field value at position xsi*length" ;
  input Real T_min "T <= T_min is mapped to colorMap[1,:]" ;
  input Real T_max "T >= T_max is mapped to colorMap[end,:]" ;
  input Real colorMap[:,3]
    "Color map to map scalar T to a corresponding color" ;
protected
  Real beta;
  Real xsi_i;
  Real Ti;
  Real Ci[3];
  Integer k;
algorithm
  k:=1;
  for i in 1:nu loop
    // Compute actual xsi-position along cylinder axis
    xsi_i := (i-1)/(nu-1);

    // Interpolate in xsi and T to determine the corresponding value of Ti(xsi_i)
    (Ti,k) := Modelica.Math.Vectors.interpolate(xsi, T, xsi_i, k);

    // Map the scalar field value Ti to a color value
    Ci := Modelica.Mechanics.MultiBody.Visualizers.Colors.scalarToColor(
      Ti,
      T_min,
      T_max,
      colorMap);

    // Determine outputs
    for j in 1:nv loop
      beta := 2*Modelica.Constants.pi*(j-1)/(nv-1);
      X[i,j] := length*xsi_i;
      Y[i,j] := rOuter*Modelica.Math.sin(beta);
      Z[i,j] := rOuter*Modelica.Math.cos(beta);
      C[i,j,:] := Ci;
    end for;
  end for;
end pipeWithScalarField;

function rectangle "Function defining the surface characteristic of a planar rectangle"
  extends Modelica.Mechanics.MultiBody.Interfaces.partialSurfaceCharacteristic(
    final multiColoredSurface=false);
  input SI.Distance lu=1 "Length in direction u" ;
  input SI.Distance lv=3 "Length in direction v" ;
algorithm
  X[:,:] := lu/2 * transpose(fill(linspace(-1,1,nu), nv));
  Y[:,:] := lv/2 * fill(linspace(-1,1,nv), nu);
  Z[:,:] := fill(0, nu, nv);
end rectangle;

function torus "Function defining the surface characteristic of a torus"
  extends Modelica.Mechanics.MultiBody.Interfaces.partialSurfaceCharacteristic(
    final multiColoredSurface=false);
  input SI.Length R=1 "Major radius (distance from center of torus to center of tube)" ;
  input SI.Length r=0.2 "Minor radius (radius of tube)" ;
  input SI.Angle opening=0 "Opening angle of torus" ;
  input SI.Angle startAngle= -Modelica.Constants.pi
    "Start angle of torus slice" ;
  input SI.Angle stopAngle= Modelica.Constants.pi
    "End angle of torus slice" ;
protected
  SI.Angle alpha;
  SI.Angle beta;
  SI.Angle phi_start;
  SI.Angle phi_stop;
algorithm
  phi_start :=-Modelica.Constants.pi + opening;
  phi_stop  :=Modelica.Constants.pi - opening;
  for i in 1:nu loop
    alpha := startAngle + (stopAngle-startAngle)*(i-1)/(nu-1);
    for j in 1:nv loop
      beta := phi_start + (phi_stop-phi_start)*(j-1)/(nv-1);
      X[i,j] := (R + r*Modelica.Math.cos(beta))*Modelica.Math.sin(alpha);
      Y[i,j] := r*Modelica.Math.sin(beta);
      Z[i,j] := (R + r*Modelica.Math.cos(beta))*Modelica.Math.cos(alpha);
    end for;
  end for;
end torus;

