          det := nDerivs.st*nDerivs.pd - nDerivs.pt*nDerivs.sd;
          delt := (nDerivs.pd*ds - nDerivs.sd*dp)/det;
          deld := (nDerivs.st*dp - nDerivs.pt*ds)/det;
          T := T - delt;
          d := d - deld;
          dguess := d;
          Tguess := T;
          i := i + 1;
          (d,T) := fixdT(dguess, Tguess);
        end while;
        if not found then
