          vap := Modelica.Media.Common.gibbsToBoundaryProps(g);
        else
          dv := Regions.rhov_p_R4b(p);
          f := Basic.f3(dv, Tsat);
          vap := Modelica.Media.Common.helmholtzToBoundaryProps(f);
        end if;
      end waterVap_p;

