model Ambient "Ambient with constant properties"

  extends FluidHeatFlow.BaseClasses.SinglePortLeft(
    final Exchange=true,
    final T0=293.15,
    final T0fixed=false);
  parameter Boolean usePressureInput=false
    "Enable / disable pressure input";
